const format = (value) => value.toLocaleString("en-US");
const icon = (name) => ({ compass: "⌖", chart: "◒", funnel: "▽", flask: "✦", spark: "✧", arrow: "↗", close: "×", check: "✓", menu: "☰" }[name] || "•");

function logo() { return `<div class="brand-mark" aria-label="Namron Hospitality"><span>NAMRON</span><small>HOSPITALITY</small></div>`; }

function header() {
  const tabs = ["Portfolio", "Brand & Demand", "Acquisition", "Conversion", "Growth Lab"];
  return `<header class="topbar">
    <div class="topbar-left">${logo()}<span class="rule"></span><span class="product-name">Growth OS</span></div>
    <nav class="main-nav" aria-label="Primary navigation">${tabs.map(tab => `<button class="nav-item ${state.tab === tab ? "active" : ""}" data-tab="${tab}">${tab}</button>`).join("")}</nav>
    <div class="topbar-right"><span class="status-dot"></span><span class="live-label">Demo environment</span><button class="icon-button" aria-label="Open AI operator" data-ai="true">${icon("spark")}</button></div>
  </header>`;
}

function demoBanner() { return `<div class="demo-banner"><span class="demo-dot"></span><span><strong>Prototype</strong> · Illustrative data · No internal Namron data used</span><span class="banner-source">Built for portfolio decision-making</span></div>`; }

function metricMeta(label) { const meta = { "Direct revenue": ["Booking engine + PMS", "property × stay date × channel", "7-day click", "92%", "Actual after reconciliation"], "Direct mix": ["PMS + booking engine + OTA", "property × room night", "Booked source", "88%", "Choose bookings, room nights, or revenue as the canonical denominator"], "Marketing spend": ["Google Ads + Meta", "property × campaign × day", "Platform reported", "98%", "Excludes offline and partner media until connected"], "Cost per booking": ["Warehouse semantic layer", "property × channel × booking", "7-day click", "86%", "Cancelled bookings excluded"], "ROAS": ["Ads + booking engine", "property × campaign × booking", "7-day click", "92%", "Booking revenue, not contribution profit"], "Booking conversion": ["GA4 + booking engine", "property × device × session", "Session to confirmed booking", "84%", "Booking-engine sessions only"], "LTV": ["CRM + PMS", "guest cohort × stay month", "Cohort", "Directional", "Requires repeat-stay and margin history"], "CPV": ["Ads + GA4", "property × qualified visit", "Last-click", "81%", "Cost per qualified visit, not cost per view"], "ADR": ["PMS / CRS", "property × stayed room night", "Stay date", "97%", "Net of discounts when connected"], "OTA commission": ["OTA / channel manager", "property × channel × booking", "Stay date", "Estimated", "Replace estimate with actual commission by channel"] }; return meta[label] || ["Illustrative warehouse", "portfolio × day", "Directional", "Illustrative", "Validate against source system"]; }
function metric(label, value, delta, tone = "positive", definition = "") { const [source, grain, attribution, confidence, caveat] = metricMeta(label); return `<article class="metric" tabindex="0" aria-label="${label}: ${definition}"><div class="metric-label"><span>${label}</span><span class="metric-info" aria-hidden="true">?</span><div class="metric-tooltip"><strong>${label}</strong><span>${definition}</span><div class="metric-lineage"><span>Source</span><b>${source}</b><span>Grain</span><b>${grain}</b><span>Attribution</span><b>${attribution}</b><span>Confidence</span><b>${confidence}</b><span>Caveat</span><b>${caveat}</b></div></div></div><div class="metric-value">${value}</div><div class="metric-foot"><span class="delta ${tone}">${delta}</span><span>vs prior 30 days</span></div></article>`; }

function selectControl(label, value, options, key) { return `<label class="filter"><span>${label}</span><select data-filter="${key}">${options.map(option => `<option ${value === option ? "selected" : ""}>${option}</option>`).join("")}</select></label>`; }

function tag(value) { return `<span class="tag tag-${value.toLowerCase()}">${value}</span>`; }

function portfolioTable() {
  const destinations = ["All destinations", ...new Set(properties.map(p => p.destination))];
  const actions = ["All actions", "Protect", "Grow", "Optimize", "Direct", "Investigate"];
  const demands = ["All demand", "Strong", "Medium", "Soft"];
  const filtered = properties.filter(p => (state.destination === "All destinations" || p.destination === state.destination) && (state.action === "All actions" || p.action === state.action) && (state.demand === "All demand" || p.demand === state.demand));
  const definitions = { demand:"Forward demand strength based on stay-date pace, availability, and current need. Strong means demand is healthy relative to available inventory; Medium means it needs monitoring; Soft means open inventory or weak pace may need support.", direct:"Direct mix is the share of bookings attributed to Namron-owned channels under the chosen production definition. Confirm whether production uses bookings, room nights, or revenue.", occ:"Stay-date occupancy is occupied rooms divided by available rooms for the selected period. Read it with pickup pace, ADR, restrictions, and need dates.", roas:"ROAS is attributed booking revenue divided by media spend. It shows revenue efficiency, not profit; defend it with commission, fees, cancellations, and contribution.", cpb:"CPB is acquisition spend divided by confirmed bookings. Lower is not automatically better if booking quality, ADR, or net contribution falls.", conv:"Conversion is booking-engine sessions that become confirmed reservations. Segment it by device, source, rate, room type, and checkout step.", decision:"The decision is the recommended operating posture: Protect, Grow, Optimize, Direct, or Investigate. It tells you what to do next, not just what the number is." };
  return `<section class="panel portfolio-panel"><div class="panel-head"><div><span class="eyebrow">Portfolio health</span><h2>Which properties need attention?</h2></div><div class="filter-row">${selectControl("Destination", state.destination, destinations, "destination")}${selectControl("Action", state.action, actions, "action")}${selectControl("Demand", state.demand, demands, "demand")}</div></div>
  <div class="matrix-wrap"><table class="health-matrix"><thead><tr><th>Account</th><th class="explainable" tabindex="0" data-tip="${definitions.demand}">Demand</th><th class="explainable" tabindex="0" data-tip="${definitions.direct}">Direct mix</th><th class="explainable" tabindex="0" data-tip="${definitions.occ}">Occ.</th><th class="explainable" tabindex="0" data-tip="${definitions.roas}">ROAS</th><th class="explainable" tabindex="0" data-tip="${definitions.cpb}">CPB</th><th class="explainable" tabindex="0" data-tip="${definitions.conv}">Conv.</th><th class="explainable" tabindex="0" data-tip="${definitions.decision}">Decision</th></tr></thead><tbody>${filtered.map(p => `<tr class="property-row ${state.selected === p.name ? "selected" : ""}" data-property="${p.name}"><td><div class="property-name"><span class="property-thumb thumb-${p.image}"></span><span>${p.name}<small>${p.destination}</small></span>${p.issue ? `<span class="issue-dot" title="Priority signal"></span>` : ""}</div></td><td><span class="demand demand-${p.demand.toLowerCase()} explainable" tabindex="0" data-tip="${definitions.demand}">${p.demand}</span></td><td><strong class="explainable" tabindex="0" data-tip="${definitions.direct}">${p.direct}%</strong></td><td><span class="explainable" tabindex="0" data-tip="${definitions.occ}">${p.occupancy}%</span></td><td><span class="explainable" tabindex="0" data-tip="${definitions.roas}">${p.roas}x</span></td><td><span class="explainable" tabindex="0" data-tip="${definitions.cpb}">$${p.cpb}</span></td><td><span class="explainable" tabindex="0" data-tip="${definitions.conv}">${p.conversion}%</span></td><td>${tag(p.action)}</td></tr>`).join("")}</tbody></table></div><div class="table-foot"><span>${filtered.length} of ${properties.length} accounts shown · click any row for account detail</span><button class="text-button" data-reset="true">Reset filters ${icon("arrow")}</button></div></section>`;
}

function storyMode() {
  const steps = [
    { kicker: "Morning brief", title: "Where should I put attention today?", body: "The portfolio is healthy overall, but one property has a clear gap between growing demand and profitable direct conversion.", cta: "Show me the signal" },
    { kicker: "Signal → diagnosis", title: "Volga is the highest-leverage move", body: "Traffic is up 14%, conversion is down 19%, and OTA share is rising. Forward occupancy is soft enough to justify a targeted intervention.", cta: "See the decision" },
    { kicker: "Decision → action", title: "Fix the funnel before buying more demand", body: "Audit the mobile booking path, confirm direct-rate parity, and launch an abandonment flow. Keep spend controlled until conversion recovers.", cta: "Open Volga detail" }
  ];
  const step = steps[state.storyStep];
  return `<aside class="story-card ${state.storyOpen ? "open" : "collapsed"}"><div class="story-top"><span class="eyebrow">Operator walkthrough</span><button class="close-button" aria-label="Close morning brief" data-story-close="true">${icon("close")}</button></div>${state.storyOpen ? `<div class="story-progress">${steps.map((_, i) => `<span class="${i <= state.storyStep ? "done" : ""}"></span>`).join("")}</div><span class="story-kicker">${step.kicker}</span><h2>${step.title}</h2><p>${step.body}</p><button class="primary-button" data-story-next="true">${step.cta}<span>${icon("arrow")}</span></button><div class="story-footer"><span>${state.storyStep + 1} / ${steps.length}</span><button class="text-button" data-architecture="true">View data architecture</button></div>` : `<button class="collapsed-story-button" data-story-open="true"><span>${icon("spark")}</span> Open morning brief</button>`}</aside>`;
}

function architectureModal() { return `<div class="modal-backdrop" data-modal-close="true"><section class="architecture-modal" role="dialog" aria-modal="true" aria-labelledby="architecture-title"><button class="close-button" data-modal-close="true" aria-label="Close">${icon("close")}</button><span class="eyebrow">System map</span><h2 id="architecture-title">From signal to decision</h2><p class="modal-lede">The dashboard is the final layer of a commercial operating system—not the source of truth.</p><div class="architecture-flow">${["APIs", "Data warehouse", "Property model", "AI analysis", "Growth OS", "Human decision", "Execution"].map((step, i) => `<div class="arch-step"><span>${String(i + 1).padStart(2, "0")}</span><strong>${step}</strong>${i < 6 ? `<i>→</i>` : ""}</div>`).join("")}</div><div class="source-list"><span>Illustrative future inputs</span><p>Google Ads · Meta · GA4 · Search Console · booking engine · PMS · CRM · OTA / channel manager · revenue management system</p></div></section></div>`; }

function detailDrawer() {
  const p = properties.find(item => item.name === state.selected) || properties[4];
  const volga = p.name === "Volga";
  const signals = volga ? [["Occupancy", "61%", "↓ 9%"], ["Website traffic", "14%", "↑"], ["Booking conversion", "2.1%", "↓ 19%"], ["OTA share", "44%", "↑ 6%"]] : [["Occupancy", `${p.occupancy}%`, p.occupancy < 70 ? "↓" : "→"], ["Direct mix", `${p.direct}%`, p.direct < 60 ? "↓" : "↑"], ["Paid ROAS", `${p.roas}x`, "↑"], ["Conversion", `${p.conversion}%`, "→"]];
  const adr = p.name === "Volga" ? 298 : Math.round(240 + p.roas * 22);
  const rooms = p.name === "The William New York" ? 33 : p.name === "Alexander Hotel" ? 144 : 18 + (p.name.length % 20);
  return `<aside class="detail-drawer"><div class="drawer-head"><div><span class="eyebrow">Account detail · ${properties.indexOf(p) + 1} of ${properties.length}</span><h2>${p.name}</h2><span class="drawer-subtitle">${p.destination} · illustrative 30-day view</span></div><button class="close-button" aria-label="Close account detail" data-drawer-close="true">${icon("close")}</button></div><div class="account-switcher"><span>Account</span><strong>${p.name}</strong><button class="text-button" data-account-next="true">Next account ${icon("arrow")}</button></div><div class="drawer-image thumb-${p.image}"><span>${tag(p.action)}</span></div><div class="account-stat-strip"><div><span>Rooms</span><strong>${rooms}</strong></div><div><span>ADR</span><strong>$${adr}</strong></div><div><span>90 day occ.</span><strong>${Math.max(31, p.occupancy - 22)}%</strong></div></div><div class="drawer-tabs"><button class="active">Overview</button><button>Acquisition</button><button>Conversion</button><button>Experiments</button></div><div class="drawer-section"><span class="eyebrow">Signals</span><div class="signal-grid">${signals.map(([label, value, delta]) => `<div><span>${label}</span><strong>${value}</strong><small class="${delta.includes("↓") ? "negative" : "positive"}">${delta}</small></div>`).join("")}</div></div><div class="drawer-section diagnosis"><span class="eyebrow">Diagnosis</span><p>${volga ? "Traffic is growing, but direct conversion is weakening. There is demand to capture, but the next dollar should go to removing booking friction—not more reach." : `${p.name} is currently tagged ${p.action.toLowerCase()} based on its blend of demand, occupancy, direct mix, and acquisition efficiency.`}</p></div><div class="drawer-section"><span class="eyebrow">Recommended actions</span><ol class="action-list">${(volga ? ["Inspect booking-engine funnel on mobile", "Compare direct rates with OTA parity", "Launch booking abandonment flow", "Reallocate incremental spend only after QA"] : ["Review source-market mix", "Check forward demand by stay date", "Add to weekly commercial review"]).map((action, i) => `<li><span>${i + 1}</span>${action}</li>`).join("")}</ol></div><button class="primary-button full" data-add-review="${p.name}">Add ${p.name} to weekly review <span>${icon("arrow")}</span></button></aside>`;
}

function operatingPillars() { const pillars = [{ name: "People", status: "Property-ready", copy: "Are GMs and local teams equipped to turn guest insight into action?", signal: "Guest experience feedback" }, { name: "Process", status: "2 handoffs open", copy: "Are campaign, revenue, booking, and property workflows connected with clear owners?", signal: "Commercial SLA health" }, { name: "Technology", status: "Tracking QA", copy: "Can the booking path, feeds, CRM, and attribution be trusted at account level?", signal: "Booking engine + feed uptime" }, { name: "Data", status: "Directional", copy: "Can we defend the number, compare like with like, and prioritize the next dollar?", signal: "Attribution confidence" }]; return `<section class="pillar-panel"><div class="panel-head"><div><span class="eyebrow">The Namron way</span><h2>Four pillars behind the growth system</h2></div><span class="period-pill">People · Process · Technology · Data</span></div><div class="pillar-grid">${pillars.map((pillar, i) => `<article class="pillar-card"><div class="pillar-top"><span class="pillar-index">0${i + 1}</span><span class="pillar-status">${pillar.status}</span></div><h3>${pillar.name}</h3><p>${pillar.copy}</p><span class="pillar-signal">${pillar.signal}</span></article>`).join("")}</div><div class="pillar-foot"><span>This is the operating layer behind the marketing metrics—not a separate report.</span><button class="text-button" data-architecture="true">See system map ${icon("arrow")}</button></div></section>`; }

function revenueSurfaces() { const surfaces = [{ name: "Rooms + direct bookings", value: "$1.24m", signal: "Direct mix · 72%", color: "sage" }, { name: "Dining + F&B", value: "$286k", signal: "Cross-sell and local demand", color: "copper" }, { name: "Events + retreats", value: "12 leads", signal: "Buyouts · weddings · groups", color: "blue" }, { name: "Wellness + experiences", value: "8.4%", signal: "Attach rate opportunity", color: "plum" }]; return `<section class="panel surface-panel"><div class="panel-head"><div><span class="eyebrow">Beyond the room</span><h2>Every revenue surface should have a growth loop</h2></div><span class="period-pill">Illustrative portfolio view</span></div><div class="surface-grid">${surfaces.map(s => `<article class="surface-card"><span class="surface-dot ${s.color}"></span><div><h3>${s.name}</h3><strong>${s.value}</strong><p>${s.signal}</p></div><button class="text-button" data-ai-action="${s.name} brief">Scan ${icon("arrow")}</button></article>`).join("")}</div></section>`; }
function workflowRail(active) { return `<nav class="workflow-rail" aria-label="Operating sequence"><span class="workflow-label">Operating sequence</span>${["Decision", "Evidence", "Diagnosis", "Action"].map(step => `<span class="workflow-step ${step === active ? "is-active" : ""}">${step}</span>`).join("")}</nav>`; }
function brandView() { return `<div class="view brand-view"><section class="hero-row compact"><div><span class="eyebrow">Brand & demand observatory</span><h1>Make the right properties<br><em>impossible to ignore.</em></h1><p class="hero-copy">A brand layer for protecting distinctiveness while making every property easier to discover, understand, choose, and book direct.</p></div><div class="hero-aside brand-aside"><span class="eyebrow">Brand health</span><strong>Distinctive · directional</strong><span>18 properties · 9 destinations · illustrative</span><button class="primary-button" data-ai-action="Brand health scan">Run brand scan <span>${icon("arrow")}</span></button></div></section>${workflowRail("Evidence")}<section class="panel brand-scorecard"><div class="panel-head"><div><span class="eyebrow">Portfolio brand health</span><h2>Is brand demand becoming commercial demand?</h2></div><span class="period-pill">Illustrative last 30 days</span></div><div class="section-question"><span>Growth question</span><strong>Are we building preference, not just buying traffic?</strong></div><div class="brand-score-grid"><div><span>Branded demand</span><strong>+18%</strong><small>Search interest · YoY</small><b class="score-positive">↑ Momentum</b></div><div><span>Nonbrand visibility</span><strong>42%</strong><small>Destination query coverage</small><b class="score-neutral">→ Build</b></div><div><span>Review health</span><strong>4.7 / 5</strong><small>Average rating · 1,248 reviews</small><b class="score-positive">↑ Strong</b></div><div><span>Creative-to-booking</span><strong>2.8%</strong><small>Qualified landing conversion</small><b class="score-warn">↓ Diagnose</b></div></div></section><section class="panel property-architecture"><div class="panel-head"><div><span class="eyebrow">Property brand architecture</span><h2>Every property has a role and a promise</h2></div><span class="period-pill">Portfolio lens</span></div><div class="brand-table"><div class="brand-table-head"><span>Property</span><span>Promise / audience</span><span>Portfolio role</span><span>Guardrail</span></div>${[{p:"Volga",promise:"Design-led Mexico City stay · culture seeker",role:"Demand recovery",guard:"Do not trade distinctiveness for discount"},{p:"La Valise Tulum",promise:"Barefoot luxury · high-intent escape",role:"Brand halo",guard:"Protect rate and scarcity"},{p:"Alexander Hotel",promise:"Urban social stay · direct capture",role:"Direct recovery",guard:"Win parity on branded demand"},{p:"NEST Baja",promise:"Remote nature · slow travel",role:"Growth bet",guard:"Sell the destination, not the room"},{p:"The William",promise:"New York intimacy · design traveler",role:"Margin protector",guard:"Prioritize qualified demand"}].map(row => `<div class="brand-table-row"><strong>${row.p}</strong><span>${row.promise}</span><b>${row.role}</b><em>${row.guard}</em></div>`).join("")}</div></section><section class="brand-two-up"><article class="panel creative-panel"><div class="panel-head"><div><span class="eyebrow">Creative-to-commercial</span><h2>Does the promise survive the click?</h2></div><span class="status-chip">3 reviews open</span></div><div class="creative-list"><div><span class="creative-mark good">✓</span><div><strong>Volga editorial suite story</strong><p>Strong brand fit · qualified traffic rising · booking path needs QA.</p></div><em>Scale carefully</em></div><div><span class="creative-mark warn">!</span><div><strong>Alexander value-led retargeting</strong><p>Conversion is efficient, but the message risks flattening the property into a commodity.</p></div><em>Review tone</em></div><div><span class="creative-mark good">✓</span><div><strong>NEST Baja destination film</strong><p>High save rate and longer session depth signal audience quality.</p></div><em>Test direct CTA</em></div></div></article><article class="panel guest-voice-panel"><div class="panel-head"><div><span class="eyebrow">Guest voice</span><h2>What are guests actually remembering?</h2></div><span class="period-pill">Illustrative signals</span></div><div class="guest-themes"><div><strong>Sense of place</strong><span>+22% mention rate</span></div><div><strong>Service warmth</strong><span>4.8 / 5 sentiment</span></div><div><strong>Booking friction</strong><span>−19% mobile completion</span></div><div><strong>F&B discovery</strong><span>8.4% attach opportunity</span></div></div><div class="panel-footline"><span>Connect reviews, post-stay survey, CRM, and experience data.</span><button class="text-button" data-ai-action="Guest voice scan">Scan themes ${icon("arrow")}</button></div></article></section><section class="panel brand-guardrails"><div class="panel-head"><div><span class="eyebrow">AI brand guardrails</span><h2>Growth recommendations must protect the soul of the property</h2></div><span class="ai-confidence">Human approval required</span></div><div class="guardrail-grid"><div><span>01</span><strong>Brand fit</strong><p>Does the action express the property’s promise?</p></div><div><span>02</span><strong>Guest fit</strong><p>Does it attract the right traveler, not just cheap traffic?</p></div><div><span>03</span><strong>Commercial fit</strong><p>Does it improve direct contribution without damaging rate?</p></div><div><span>04</span><strong>Experience fit</strong><p>Can operations deliver what the message promises?</p></div></div><div class="panel-footline"><span>AI can rank and explain. Rafael, brand, revenue, and property owners decide.</span><button class="text-button" data-ai-action="Brand guardrail review">Review guardrails ${icon("arrow")}</button></div></section></div>`; }
function strategyDiagram() { return `<section class="panel strategy-diagram"><div class="panel-head"><div><span class="eyebrow">The Namron growth logic</span><h2>Brand strategy creates resonance; the four pillars make it repeatable</h2></div><span class="period-pill">Operating model</span></div><div class="section-question"><span>Strategic question</span><strong>How does a distinctive idea become a measurable, repeatable commercial system?</strong></div><div class="strategy-map"><div class="strategy-node strategy-core"><span>Brand strategy</span><strong>Generate resonance</strong><small>Sense of place · emotional preference · cultural relevance</small></div><div class="strategy-connectors"><i></i><i></i><i></i><i></i></div><div class="strategy-pillars"><div><span>01</span><strong>People</strong><small>Local protagonists turn the promise into a lived experience.</small></div><div><span>02</span><strong>Process</strong><small>Clear handoffs move insight from campaign to property action.</small></div><div><span>03</span><strong>Technology</strong><small>Invisible systems make discovery, booking, and measurement work.</small></div><div><span>04</span><strong>Data</strong><small>Evidence shows what is resonating and where to intervene.</small></div></div><div class="strategy-output"><span>Resonance</span><b>→</b><span>Qualified demand</span><b>→</b><span>Direct preference</span><b>→</b><span>Profitable stay</span><b>→</b><span>Repeat memory</span></div></div><div class="panel-footline"><span>Brand creates the reason to care. The operating system creates the ability to scale what works.</span><button class="text-button" data-architecture="true">Open system map ${icon("arrow")}</button></div></section>`; }
function pillarMeasurementPanel() { const pillars = [{name:"People", outcome:"Action adoption", kpi:"85%", definition:"Actions with a named owner, due date, and completed outcome.", evidence:"Decision ledger · property review · guest insight", owner:"Property + Growth", cadence:"Weekly"},{name:"Process", outcome:"Decision cycle time", kpi:"≤ 7 days", definition:"Time from a trusted signal to an approved action in-market.", evidence:"Campaign · revenue · property handoffs", owner:"Growth Ops", cadence:"Weekly"},{name:"Technology", outcome:"Path reliability", kpi:"≥ 98%", definition:"Healthy booking, feed, event, and tracking coverage across properties.", evidence:"Booking engine · channel manager · GA4 QA", owner:"Digital", cadence:"Daily"},{name:"Data", outcome:"Decision confidence", kpi:"≥ 90%", definition:"Source completeness and reconciliation strong enough to defend a number.", evidence:"Warehouse lineage · QA · attribution", owner:"Analytics", cadence:"Weekly / monthly"}]; const flywheel = [{name:"Reach", measure:"Qualified nonbrand demand", signal:"Search Console · AEO / GEO visibility · destination CTR", decision:"Where should we create attention?"},{name:"Resonance", measure:"Brand preference", signal:"Branded search lift · saves · reviews · direct navigation", decision:"What is making the property memorable?"},{name:"Reputation", measure:"Trust and advocacy", signal:"Review rating · review volume · sentiment · recommendation intent", decision:"Do guests and the market trust the promise?"},{name:"Revenue", measure:"Direct contribution", signal:"Net revenue − channel cost − discounts − payment fees", decision:"Which investment creates profitable growth?"}]; const investments = [{property:"Volga",thesis:"Fix → grow",investment:"Mobile CRO before reach",proof:"Booking completion + direct contribution",owner:"Growth",confidence:"Directional"},{property:"La Valise Tulum",thesis:"Protect",investment:"Rate + scarcity + brand search",proof:"ADR · direct mix · net contribution",owner:"Brand + Revenue",confidence:"Directional"},{property:"Alexander Hotel",thesis:"Direct capture",investment:"Parity + metasearch + retargeting",proof:"OTA share down · direct mix up",owner:"Acquisition",confidence:"Directional"},{property:"NEST Baja",thesis:"Test",investment:"Destination storytelling + qualified demand",proof:"Qualified sessions · stayed bookings",owner:"Brand + Growth",confidence:"Exploratory"},{property:"MUSA",thesis:"Grow",investment:"Need-date paid demand",proof:"90-day occupancy · contribution",owner:"Revenue + Growth",confidence:"Exploratory"}]; return `<section class="panel pillar-measurement"><div class="panel-head"><div><span class="eyebrow">Measurement layer</span><h2>How do we know the operating system is working?</h2></div><span class="period-pill">Portfolio scorecard</span></div><div class="section-question"><span>Measurement question</span><strong>Which capability is helping each brand turn resonance into profitable, repeatable demand?</strong></div><div class="pillar-measure-grid">${pillars.map(p => `<article><div class="pillar-measure-top"><span>${p.name}</span><b>${p.kpi}</b></div><strong>${p.outcome}</strong><p>${p.definition}</p><small>${p.evidence}</small><footer><span>${p.owner}</span><em>${p.cadence}</em></footer></article>`).join("")}</div><div class="panel-footline"><span>Each pillar has an outcome, evidence source, owner, and review cadence—so it can change a decision.</span><span class="decision-caption">Not a maturity score</span></div></section><section class="panel flywheel-measurement"><div class="panel-head"><div><span class="eyebrow">Brand strategy measurement</span><h2>Reach, resonance, reputation, revenue</h2></div><span class="period-pill">Flywheel signals</span></div><div class="flywheel-grid">${flywheel.map((f, i) => `<article><span class="flywheel-index">0${i + 1}</span><h3>${f.name}</h3><strong>${f.measure}</strong><p>${f.signal}</p><small>${f.decision}</small></article>`).join("")}</div><div class="panel-footline"><span>Brand metrics are leading signals; contribution and stayed revenue are the commercial proof.</span><span class="decision-caption">Connect to source systems</span></div></section><section class="panel investment-allocation"><div class="panel-head"><div><span class="eyebrow">Portfolio investment thesis</span><h2>Every property earns a different kind of attention</h2></div><span class="period-pill">Illustrative allocation logic</span></div><div class="section-question"><span>Investment question</span><strong>Where should the next dollar, hour, or experiment go—and what evidence would justify it?</strong></div><div class="investment-table"><div class="investment-head"><span>Property</span><span>Thesis</span><span>Investment</span><span>Proof of value</span><span>Owner</span><span>Confidence</span></div>${investments.map(row => `<div class="investment-row"><strong>${row.property}</strong><b>${row.thesis}</b><span>${row.investment}</span><span>${row.proof}</span><em>${row.owner}</em><small>${row.confidence}</small></div>`).join("")}</div><div class="panel-footline"><span>Production version: allocate against contribution margin, need dates, marginal demand, and brand guardrails—not ROAS alone.</span><button class="text-button" data-ai-action="Investment allocation review">Review allocation ${icon("arrow")}</button></div></section>`; }
function portfolioContextPanel() { return `<section class="portfolio-context-grid"><article class="panel context-panel"><div class="panel-head"><div><span class="eyebrow">Revenue management lens</span><h2>Need dates before more spend</h2></div><span class="period-pill">Stay-date view</span></div><div class="context-stats"><div><span>RevPAR</span><strong>$206</strong><small>Revenue per available room</small></div><div><span>Pickup pace</span><strong>+8.4%</strong><small>Bookings added vs prior week</small></div><div><span>Booking window</span><strong>42 days</strong><small>Average days before arrival</small></div><div><span>Length of stay</span><strong>3.2 nights</strong><small>Average stayed booking</small></div></div><p class="context-note">Spend is only incremental when the property has open inventory, healthy rate, and a measurable need date.</p></article><article class="panel context-panel lifecycle-panel"><div class="panel-head"><div><span class="eyebrow">Portfolio lifecycle</span><h2>Measure the stage, not just the score</h2></div><span class="period-pill">18 accounts</span></div><div class="lifecycle-list"><div><strong>Pre-opening</strong><span>Awareness · qualified demand · CRM capture</span><b>2</b></div><div><strong>Ramp-up</strong><span>Pickup · direct mix · booking pace</span><b>3</b></div><div><strong>Mature</strong><span>Contribution · repeat value · rate protection</span><b>11</b></div><div><strong>Repositioning</strong><span>Demand recovery · offer testing · QA</span><b>2</b></div></div></article></section>`; }
function portfolioPlanPanel() { return `<section class="panel portfolio-plan"><div class="panel-head"><div><span class="eyebrow">Commercial plan</span><h2>Are we on pace for the revenue we want?</h2></div><span class="period-pill">Illustrative FY26 plan</span></div><div class="plan-grid"><div><span>Direct revenue target</span><strong>$15.8m</strong><small>Portfolio goal</small></div><div><span>Current run-rate</span><strong>$16.3m</strong><small>Forecast at current pace</small></div><div><span>Target direct mix</span><strong>75%</strong><small>Current: 72%</small></div><div class="plan-gap"><span>Plan variance</span><strong>+$0.5m</strong><small>Positive pace · protect margin</small></div></div><div class="plan-bar"><span style="width:82%"></span></div><div class="panel-footline"><span>Portfolio target = property revenue plans + direct contribution ambition.</span><button class="text-button" data-ai-action="Revenue plan review">Defend the plan ${icon("arrow")}</button></div></section>`; }
function detailTargetPanel() { const p = properties.find(item => item.name === state.selected) || properties[4]; const targetOcc = p.name === "Volga" ? 72 : Math.min(94, Math.max(p.occupancy + 3, 78)); const targetDirect = p.action === "Direct" ? Math.min(82, p.direct + 10) : p.action === "Grow" ? Math.min(78, p.direct + 6) : Math.min(85, p.direct + 3); const pace = p.occupancy >= targetOcc ? "On pace" : "Needs attention"; return `<div class="account-goal-panel"><div class="goal-head"><span class="eyebrow">Account plan</span><span class="goal-status ${pace === "On pace" ? "good" : "warn"}">${pace}</span></div><div class="goal-grid"><div><span>90-day occ. target</span><strong>${targetOcc}%</strong><small>Current ${Math.max(31, p.occupancy - 22)}%</small></div><div><span>Direct mix target</span><strong>${targetDirect}%</strong><small>Current ${p.direct}%</small></div><div><span>Decision lens</span><strong>${p.action}</strong><small>Based on demand + margin</small></div></div><p>Targets are illustrative placeholders until revenue-management, PMS, booking-engine, and distribution economics are connected.</p></div>`; }
function detailClarityPanel() { const p = properties.find(item => item.name === state.selected) || properties[4]; const interpretation = { Protect: "Preserve rate, direct preference, and guest quality because demand or occupancy is already strong.", Grow: "Create qualified demand for open inventory, but only after conversion and contribution economics are understood.", Optimize: "Improve efficiency, message, or conversion before adding meaningful incremental budget.", Direct: "Reduce OTA dependence by improving owned-channel capture, parity, and direct guest relationship.", Investigate: "Resolve the data, demand, or distribution uncertainty before scaling an intervention." }; const change = p.action === "Investigate" ? "A reconciled source or confirmed root cause" : p.action === "Protect" ? "A material pace decline or rate-risk signal" : "A change in occupancy, conversion, parity, or contribution margin"; return `<div class="account-clarity-panel"><div class="section-question"><span>Account question</span><strong>What should this property achieve next?</strong></div><div class="account-clarity-grid"><div><span>Interpretation</span><p>${interpretation[p.action]}</p></div><div><span>What would change the decision?</span><p>${change} would trigger a re-prioritization.</p></div><div><span>Next proof point</span><p>Assign an owner, set a decision date, and compare the actual result with the expected impact.</p></div></div></div>`; }
function implementationPlaybook() { const p = properties.find(item => item.name === state.selected) || properties[4]; const tactics = p.action === "Grow" ? [{area:"Paid media",action:"Shift incremental budget into high-intent destination and property campaigns; exclude dates already pacing strong.",metric:"Incremental direct contribution",when:"Today"},{area:"SEO",action:"Refresh the destination page around one high-intent query, improve internal links, and validate hotel/room structured data.",metric:"Qualified organic sessions",when:"This week"},{area:"CRO",action:"Audit mobile booking speed, rate display, room selection, and checkout errors before scaling traffic.",metric:"Booking-engine completion",when:"Today"},{area:"CRM",action:"Launch abandonment and pre-arrival sequences with a property-specific reason to book direct.",metric:"Recovered direct bookings",when:"This week"}] : [{area:"Paid media",action:"Protect efficient campaigns and move budget only when stay-date need and contribution margin justify it.",metric:"Net contribution per dollar",when:"Weekly"},{area:"SEO",action:"Map brand and nonbrand demand to the property promise; refresh pages with weak intent match.",metric:"Nonbrand visibility + CTR",when:"This month"},{area:"CRO",action:"Check rate parity, mobile completion, landing-page promise, and booking-engine friction.",metric:"Booking conversion",when:"This week"},{area:"CRM",action:"Add the property to a repeat, post-stay, or cross-property lifecycle path.",metric:"Repeat direct revenue",when:"This month"}]; return `<section class="drawer-section implementation-playbook"><div class="section-question"><span>Implementation question</span><strong>What do we actually do next?</strong></div><div class="tactic-list">${tactics.map((t,i) => `<article class="tactic-row"><span class="tactic-number">0${i+1}</span><div><span class="tactic-area">${t.area}</span><strong>${t.action}</strong><small>Success metric · ${t.metric}</small></div><em>${t.when}</em><button class="subtle-button" data-tactic="${t.area}">Queue</button></article>`).join("")}</div></section>`; }
function accountJourneyPanel() { const p = properties.find(item => item.name === state.selected) || properties[4]; const volga = p.name === "Volga"; const stages = volga ? [{name:"Awareness",value:"100%",note:"Qualified reach",tip:"People who could plausibly travel to this destination and fit the property audience."},{name:"Discovery",value:"68%",note:"Site sessions",tip:"People who reached the property or destination site after seeing a relevant message."},{name:"Consideration",value:"11%",note:"Booking intent",tip:"Visitors who searched dates, viewed rooms, or entered the booking engine."},{name:"Booking",value:"2.1%",note:"Confirmed",tip:"Booking-engine sessions that became confirmed reservations."},{name:"Stay",value:"1.9%",note:"Stayed",tip:"Confirmed bookings that completed the stay, excluding cancellations and no-shows."},{name:"Repeat",value:"0.8%",note:"Return value",tip:"Guests who returned or generated another direct purchase in the cohort window."}] : [{name:"Awareness",value:"100%",note:"Qualified reach",tip:"People who could plausibly travel to this destination and fit the property audience."},{name:"Discovery",value:"74%",note:"Site sessions",tip:"People who reached the property or destination site after seeing a relevant message."},{name:"Consideration",value:"16%",note:"Booking intent",tip:"Visitors who searched dates, viewed rooms, or entered the booking engine."},{name:"Booking",value:`${p.conversion}%`,note:"Confirmed",tip:"Booking-engine sessions that became confirmed reservations."},{name:"Stay",value:`${Math.max(1.8, p.conversion - .3).toFixed(1)}%`,note:"Stayed",tip:"Confirmed bookings that completed the stay, excluding cancellations and no-shows."},{name:"Repeat",value:"1.4%",note:"Return value",tip:"Guests who returned or generated another direct purchase in the cohort window."}]; return `<section class="drawer-section account-journey"><div class="section-question"><span>Journey question</span><strong>Where does this account lose value before repeat demand?</strong></div><div class="journey-flow">${stages.map((stage,i) => `<div class="journey-stage"><span class="journey-index">0${i+1}</span><strong class="explainable" tabindex="0" data-tip="${stage.tip}">${stage.name}</strong><b>${stage.value}</b><small>${stage.note}</small></div>${i < stages.length - 1 ? `<i>→</i>` : ""}`).join("")}</div><p class="journey-diagnosis"><strong>Illustrative read:</strong> ${volga ? "Volga’s largest gap is between discovery and confirmed booking. Investigate mobile friction and message-to-landing-page fit before scaling demand." : `${p.name} is currently ${p.action.toLowerCase()}; compare the largest stage drop with rate, occupancy, source market, and guest-quality signals.`}</p></section>`; }
function tacticsQueuePanel() { return `<section class="panel tactics-queue"><div class="panel-head"><div><span class="eyebrow">Execution queue</span><h2>Advice translated into work</h2></div><span class="period-pill">Next 7 days</span></div><div class="tactics-board"><div><span>SEO</span><strong>Refresh 3 destination pages</strong><small>Owner · Brand & Demand · Metric · qualified organic sessions</small><b>Ready</b></div><div><span>Paid media</span><strong>Reallocate spend by need date</strong><small>Owner · Acquisition · Metric · net direct contribution</small><b>Needs approval</b></div><div><span>CRO</span><strong>Audit Volga mobile booking path</strong><small>Owner · Growth · Metric · booking-engine completion</small><b>In progress</b></div><div><span>CRM</span><strong>Build abandonment + winback flow</strong><small>Owner · Lifecycle · Metric · recovered direct bookings</small><b>Planning</b></div></div><div class="panel-footline"><span>Every tactic has a channel, owner, timing, and success metric.</span><button class="text-button" data-ai-action="Tactics implementation brief">Create implementation brief ${icon("arrow")}</button></div></section>`; }
function sourceDeskPanel() { return `<section class="panel source-desk"><div class="panel-head"><div><span class="eyebrow">Research desk</span><h2>What should we investigate before making the number real?</h2></div><span class="period-pill">Official public sources</span></div><div class="section-question"><span>Research question</span><strong>Which public facts, property promises, and commercial assumptions still need validation?</strong></div><div class="source-desk-grid"><div><span>01 · Namron context</span><p>Confirm portfolio, four pillars, brand language, openings, dining, events, and partnership priorities.</p><a href="https://www.namronhospitality.com/" target="_blank" rel="noreferrer">Open homepage ↗</a><a href="https://www.namronhospitality.com/about-us" target="_blank" rel="noreferrer">Open About ↗</a></div><div><span>02 · Demand surfaces</span><p>Map every official stay, dining, wellness, event, and partner surface to an owner and measurable conversion path.</p><a href="https://www.namronhospitality.com/stay" target="_blank" rel="noreferrer">Open Stay ↗</a><a href="https://www.namronhospitality.com/dining" target="_blank" rel="noreferrer">Open Dining ↗</a></div><div><span>03 · Property truth</span><p>Validate the promise, room inventory, rate positioning, source markets, reviews, and official booking path for each account.</p><a href="https://www.namronhospitality.com/partner" target="_blank" rel="noreferrer">Open Partner ↗</a><a href="https://www.namronhospitality.com/careers" target="_blank" rel="noreferrer">Open Careers ↗</a></div><div><span>04 · Questions to bring to Rafael</span><p>Which properties are growth bets? Which are margin protectors? What does he consider brand health? Where is the current source of truth?</p><button class="text-button" data-ai-action="Rafael research questions">Add interview questions ${icon("arrow")}</button></div></div><div class="panel-footline"><span>Public links are research references only. No internal system is connected in this prototype.</span><span class="decision-caption">Validate before modeling.</span></div></section>`; }
function distributionHealthPanel() { return `<section class="panel distribution-health"><div class="panel-head"><div><span class="eyebrow">Commerce infrastructure</span><h2>Can the portfolio actually sell?</h2></div><span class="status-chip">2 checks open</span></div><div class="health-check-grid"><div><span class="health-check-status good">✓</span><div><strong>Property and rate feed</strong><p>18 properties mapped · illustrative freshness 14 min</p></div><em>Healthy</em></div><div><span class="health-check-status warn">!</span><div><strong>Direct-rate parity</strong><p>Alexander and Volga need a rate comparison against OTA inventory.</p></div><em>Review</em></div><div><span class="health-check-status good">✓</span><div><strong>Booking-engine availability</strong><p>Landing pages and room inventory are present for tracked properties.</p></div><em>Healthy</em></div><div><span class="health-check-status warn">!</span><div><strong>Mobile completion</strong><p>Volga completion is down 19% while traffic is rising.</p></div><em>Action</em></div></div><div class="panel-footline"><span>Future sources: PMS · CRS · channel manager · Hotel Center · booking engine</span><button class="text-button" data-ai-action="Distribution health review">Review data contract ${icon("arrow")}</button></div></section>`; }
function commercialEconomicsPanel() { return `<section class="panel economics-panel"><div class="panel-head"><div><span class="eyebrow">Commercial economics</span><h2>Optimize contribution, not just ROAS</h2></div><span class="period-pill">Illustrative portfolio view</span></div><div class="economics-grid"><div><span>Direct net revenue</span><strong>$812k</strong><small>After payment fees and discounts</small></div><div><span>OTA distribution cost</span><strong>$48k</strong><small>Commission + channel fees</small></div><div><span>Contribution margin</span><strong>64.2%</strong><small>After acquisition and distribution cost</small></div><div class="economics-highlight"><span>Direct value advantage</span><strong>+$31.4k</strong><small>Estimated retained value vs OTA mix</small></div></div><div class="panel-footline"><span>Production formula: net revenue − distribution cost − acquisition cost − cancellation loss</span><button class="text-button" data-ai-action="Contribution margin review">Defend margin ${icon("arrow")}</button></div></section>`; }
function dataTrustPanel() { return `<section class="panel data-trust-panel"><div class="panel-head"><div><span class="eyebrow">Data trust layer</span><h2>Separate signal from certainty</h2></div><span class="period-pill">Illustrative QA</span></div><div class="trust-grid"><div><span>Source coverage</span><strong>6 / 6</strong><small>systems mapped</small></div><div><span>Freshness</span><strong>14 min</strong><small>latest warehouse load</small></div><div><span>Attribution</span><strong>Directional</strong><small>model not yet validated</small></div><div><span>Exceptions</span><strong>2 open</strong><small>need owner review</small></div></div><div class="panel-footline"><span>Every insight should carry source, window, grain, confidence, and caveat.</span><button class="text-button" data-ai="true">Ask AI to defend the number ${icon("arrow")}</button></div></section>`; }
function humanLoopPanel() { return `<section class="panel human-loop-panel"><div class="panel-head"><div><span class="eyebrow">Human-in-the-loop</span><h2>Insight becomes value when someone owns the next move</h2></div><span class="period-pill">Operating cadence</span></div><div class="human-loop"><div><span>01</span><strong>Detect</strong><p>AI identifies a material change.</p></div><i>→</i><div><span>02</span><strong>Defend</strong><p>Analyst reviews source and confidence.</p></div><i>→</i><div><span>03</span><strong>Decide</strong><p>Owner accepts, rejects, or edits.</p></div><i>→</i><div><span>04</span><strong>Learn</strong><p>Outcome feeds the next review.</p></div></div><div class="panel-footline"><span>Recommended fields: owner · due date · expected impact · decision note · actual result</span><button class="text-button" data-ai-action="Human decision loop">Add to weekly review ${icon("arrow")}</button></div></section>`; }
function decisionLogPanel() { const rows = [{ id: "volga", title: "Fix Volga mobile funnel", owner: "Growth · Nina", due: "24 Sep", impact: "+$18k direct contribution", evidence: "Traffic +14% · conversion −19%" }, { id: "alexander", title: "Validate Alexander rate parity", owner: "Acquisition · Rafael", due: "26 Sep", impact: "+7 pts direct mix", evidence: "OTA share 52% · direct mix 48%" }, { id: "nest", title: "Test NEST Baja demand capture", owner: "Revenue · Kristina", due: "30 Sep", impact: "+12 stayed bookings", evidence: "90-day occupancy 49% · ROAS 3.8x" }]; return `<section class="panel decision-log"><div class="panel-head"><div><span class="eyebrow">Decision ledger</span><h2>Recommendations with a memory</h2></div><span class="period-pill">Weekly review</span></div><div class="decision-list">${rows.map(row => { const status = state.decisionStatus[row.id] || "Pending"; return `<article class="decision-row"><div class="decision-status ${status.toLowerCase()}">${status}</div><div><strong>${row.title}</strong><p>${row.evidence}</p></div><div><span>Owner</span><b>${row.owner}</b></div><div><span>Due</span><b>${row.due}</b></div><div><span>Expected impact</span><b>${row.impact}</b></div><div class="decision-actions"><button class="subtle-button" data-decision="${row.id}:Accepted">Accept</button><button class="subtle-button" data-decision="${row.id}:Rejected">Reject</button></div></article>`; }).join("")}</div><div class="panel-footline"><span>After execution: record actual outcome and compare against expected impact.</span><span class="decision-caption">Accepted decisions become learning data.</span></div></section>`; }
function dataAccessPanel() { return `<section class="panel data-access-panel"><div class="panel-head"><div><span class="eyebrow">Production data contract</span><h2>What needs to be connected</h2></div><span class="period-pill">Minimum viable stack</span></div><div class="access-grid">${["PMS / CRS · reservations, room nights, rate, stays", "Booking engine · search, availability, checkout, payment", "Google Ads + Meta · spend, campaigns, conversions", "GA4 + Search Console · sessions, source, search demand", "CRM + lifecycle · cohorts, repeat bookings, unsubscribes", "OTA / channel manager · commission, parity, cancellations", "Revenue management · pickup, forecast, restrictions", "Property master · rooms, owners, lifecycle, currency"].map((item, i) => `<div><span>0${i + 1}</span><strong>${item}</strong><em>Read-only first</em></div>`).join("")}</div><div class="panel-footline"><span>Start with hashed IDs, role-based access, currency normalization, timezone rules, and metric ownership.</span><button class="text-button" data-ai-action="Data access checklist">Open checklist ${icon("arrow")}</button></div></section>`; }

function aiDrawer() { return `<aside class="ai-drawer ${state.aiOpen ? "open" : ""}"><div class="drawer-head"><div><span class="eyebrow">Decision support</span><h2>AI Growth Analyst</h2><span class="drawer-subtitle">Portfolio intelligence layer</span></div><button class="close-button" aria-label="Close AI operator" data-ai-close="true">${icon("close")}</button></div><div class="ai-intro"><span class="ai-orb">${icon("spark")}</span><div><strong>18 accounts scanned</strong><p>Recommendations are ranked by potential impact on profitable direct revenue.</p></div></div><div class="ai-scan-status"><span class="status-dot"></span><span>Illustrative scan complete</span><strong>6 / 6 systems mapped</strong></div><div class="ai-section"><div class="ai-section-head"><span class="eyebrow">Recommended today</span><span class="ai-confidence">Confidence · directional</span></div><div class="recommendation-stack"><div class="recommendation-row"><span class="recommendation-rank">01</span><div><strong>Protect La Valise Tulum</strong><p>91% occupancy and 6.2x ROAS suggest incremental spend is less valuable than preserving rate and direct mix.</p></div><button class="subtle-button" data-ai-action="Protect">Queue</button></div><div class="recommendation-row"><span class="recommendation-rank">02</span><div><strong>Fix Volga before scaling</strong><p>Traffic is up, but conversion is down. Audit the mobile path before buying more demand.</p></div><button class="subtle-button" data-property="Volga">Open</button></div><div class="recommendation-row"><span class="recommendation-rank">03</span><div><strong>Test Alexander direct capture</strong><p>48% direct mix and high OTA exposure make rate parity and brand search a credible experiment.</p></div><button class="subtle-button" data-ai-action="Experiment">Queue</button></div></div></div><div class="ai-section"><div class="ai-section-head"><span class="eyebrow">Search visibility scan</span><span class="ai-confidence">AEO · SEO · GEO</span></div><div class="search-scan"><div><span class="search-code">AEO</span><div><strong>Answer Engine Optimization</strong><p>Are Namron properties easy for AI assistants to explain and recommend?</p></div><em class="scan-score">Needs audit</em></div><div><span class="search-code">SEO</span><div><strong>Search Engine Optimization</strong><p>Which destination pages win nonbrand demand and convert it to direct bookings?</p></div><em class="scan-score good">Scan ready</em></div><div><span class="search-code">GEO</span><div><strong>Generative Experience Optimization</strong><p>Are distinctive property facts, rates, and experiences present in generative answers?</p></div><em class="scan-score">Needs data</em></div></div><button class="secondary-button full-width" data-ai-action="Search scan">Run search visibility brief <span>${icon("arrow")}</span></button></div><div class="ai-section"><div class="ai-section-head"><span class="eyebrow">Defend the number</span><span class="ai-confidence">Explainable by design</span></div><div class="number-defense"><div><span>ROAS</span><strong>5.4x</strong><p>Attributed booking revenue ÷ advertising spend</p></div><div><span>Direct mix</span><strong>72%</strong><p>Direct bookings ÷ total bookings</p></div><div><span>LTV</span><strong>$2,840</strong><p>Estimated repeat + initial guest revenue</p></div></div><p class="defense-note">When connected, the analyst should show source, window, attribution model, comparison, confidence, and what would change the decision.</p></div><div class="ai-section"><div class="ai-section-head"><span class="eyebrow">Connected systems</span><span class="ai-confidence">Prototype map</span></div><div class="systems-grid">${["Google Ads", "Meta", "GA4", "Search Console", "Booking engine", "CRM / PMS"].map(name => `<span><i class="connected-dot"></i>${name}</span>`).join("")}</div><button class="secondary-button full-width" data-ai-action="Data connection map">View connection map <span>${icon("arrow")}</span></button></div><div class="ai-section"><div class="ai-section-head"><span class="eyebrow">Portfolio alerts</span><span class="ai-confidence">Needs review</span></div><div class="insight-list">${insights.map((item, i) => `<article class="insight-card"><div class="insight-meta"><span class="insight-icon">${item.icon}</span><span>${item.type}</span><span class="insight-rank">0${i + 1}</span></div><h3>${item.title}</h3><p>${item.body}</p><button class="subtle-button" data-insight="${i}">${item.action}<span>${icon("arrow")}</span></button></article>`).join("")}</div></div></aside>`; }

function portfolioView() { return `<div class="view portfolio-view"><section class="hero-row"><div><span class="eyebrow">Tuesday · 22 September 2026 · Portfolio command center</span><h1>Grow the right<br><em>direct revenue.</em></h1><p class="hero-copy">A daily operating view for deciding where money, attention, and experiments create the most profitable incremental demand.</p></div><div class="hero-aside"><div class="brief-label"><span class="pulse"></span> Morning brief</div><strong>1 priority move</strong><span>Volga · Mexico City</span><button class="text-button" data-property="Volga">Open diagnosis ${icon("arrow")}</button></div></section><div class="metrics-grid">${metric("Direct revenue", "$1.24m", "+12.4%", "positive", "Revenue from reservations made through Namron’s own booking channels. It matters because direct bookings usually avoid OTA commission.")}${metric("Direct mix", "72.0%", "+3.1 pts", "positive", "The percentage of total bookings that came through direct channels instead of online travel agencies.")}${metric("Marketing spend", "$75.5k", "−4.8%", "neutral", "Paid media and lifecycle investment used to create and capture demand during the selected period.")}${metric("Cost per booking", "$118", "−11.2%", "positive", "Marketing spend divided by attributed bookings. Lower is better when booking quality and revenue stay healthy.")}${metric("ROAS", "5.4x", "+0.6x", "positive", "Return on ad spend: attributed booking revenue divided by advertising spend. A 5.4x ROAS means $5.40 of revenue for every $1 spent.")}${metric("Booking conversion", "3.1%", "+0.4 pts", "positive", "The percentage of qualified website or booking-engine sessions that become a reservation.")}${metric("LTV", "$2,840", "+8.6%", "positive", "Lifetime value: the estimated total revenue a guest generates across repeat stays and additional direct purchases.")}${metric("CPV", "$0.54", "−7.2%", "positive", "Cost per visit: marketing spend divided by qualified website visits. It helps separate cheap traffic from efficient demand creation.")}${metric("ADR", "$286", "+2.8%", "positive", "Average daily rate: average room revenue earned per occupied room night. It keeps growth tied to rate, not just volume.")}${metric("OTA commission", "$48k", "−5.1%", "positive", "Estimated commission paid to online travel agencies. Increasing direct mix can reduce this distribution cost.")}</div><div class="measurement-note"><div><span class="note-icon">⌁</span><div><strong>Numbers you can defend</strong><p>Hover any metric for its plain-language definition and commercial meaning.</p></div></div><div><span>Window</span><strong>Last 30 days</strong></div><div><span>Source state</span><strong>Illustrative warehouse</strong></div><div><span>QA</span><strong class="qa-good">2 checks open</strong></div><div><span>Formula</span><strong>Direct mix = direct ÷ total bookings</strong></div></div>${portfolioTable()}${operatingPillars()}${revenueSurfaces()}</div>`; }

function acquisitionView() { return `<div class="view"><section class="hero-row compact"><div><span class="eyebrow">Acquisition control center</span><h1>Put spend where<br><em>inventory needs it.</em></h1><p class="hero-copy">Channel efficiency is only useful when it is read alongside occupancy, ADR, and the cost of filling the next room.</p></div><div class="hero-aside recommendation"><span class="eyebrow">Allocation recommendation</span><strong>+18% to high-intent demand</strong><span>Prioritize Volga, NEST Baja, and MUSA.</span><button class="primary-button" data-ai="true">Review signals <span>${icon("arrow")}</span></button></div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">Channel mix</span><h2>What the acquisition machine is producing</h2></div><span class="period-pill">Last 30 days</span></div><div class="channel-grid">${channels.map(c => `<article class="channel-card"><div class="channel-top"><span class="channel-mark ${c.tone}"></span><div><h3>${c.name}</h3><p>${c.detail}</p></div><button class="kebab" aria-label="More options for ${c.name}" data-ai-action="${c.name} channel detail">···</button></div><div class="channel-stats"><div><span>Spend</span><strong>${c.spend}</strong></div><div><span>Revenue</span><strong>${c.revenue}</strong></div><div><span>Bookings</span><strong>${c.bookings}</strong></div><div><span>ROAS</span><strong>${c.roas}</strong></div><div><span>CPB</span><strong>${c.cpb}</strong></div></div><div class="channel-bar"><span style="width:${Math.min(94, parseInt(c.roas) * 12)}%"></span></div></article>`).join("")}</div></section><section class="split-grid"><article class="panel direct-ota"><div class="panel-head"><div><span class="eyebrow">Distribution efficiency</span><h2>Direct vs OTA</h2></div><span class="status-chip">+3 pts opportunity</span></div><div class="ratio"><div><strong>72%</strong><span>Direct</span></div><div class="ratio-bar"><span></span></div><div><strong>28%</strong><span>OTA</span></div></div><div class="money-grid"><div><span>Direct revenue</span><strong>$894k</strong><small>Acquisition cost $61k</small></div><div><span>OTA revenue</span><strong>$346k</strong><small>Illustrative commission $48k</small></div><div class="opportunity"><span>Commission savings at +3 pts</span><strong>+$10.4k</strong><small>Potential direct revenue retained</small></div></div></article><article class="panel demand-panel"><div class="panel-head"><div><span class="eyebrow">Revenue management signal</span><h2>Forward demand</h2></div></div><div class="demand-table"><div class="demand-head"><span>Property</span><span>30 day</span><span>60 day</span><span>90 day</span><span>ADR</span><span>Need</span></div>${properties.slice(0,5).map(p => `<div class="demand-row"><span>${p.name}</span><strong>${p.occupancy}%</strong><span>${Math.max(38,p.occupancy - 10)}%</span><span>${Math.max(31,p.occupancy - 22)}%</span><span>$${[342,286,412,248,298][properties.indexOf(p)]}</span>${tag(p.occupancy < 65 ? "High" : p.occupancy > 85 ? "Low" : "Med")}</div>`).join("")}</div></article></section></div>`; }

function conversionView() { const funnel = [["Demand", "1.2m", "Impressions", "—"], ["Website", "140k", "Sessions", "11.7%"], ["Booking intent", "18k", "Engine visits", "12.9%"], ["Bookings", "4,200", "Reservations", "23.3%"], ["Stayed bookings", "3,850", "Completed stays", "91.7%"], ["Direct revenue", "$894k", "Net room revenue", "—"]]; return `<div class="view"><section class="hero-row compact"><div><span class="eyebrow">Conversion observatory</span><h1>Find the drop before<br><em>it becomes a gap.</em></h1><p class="hero-copy">A clean view of where intent is lost between discovery, booking, and stayed revenue.</p></div><div class="hero-aside anomaly"><span class="eyebrow">Largest illustrative drop</span><strong>Mobile engine completion</strong><span>Volga · −19% vs prior period</span><button class="text-button" data-property="Volga">Inspect property ${icon("arrow")}</button></div></section><section class="panel funnel-panel"><div class="panel-head"><div><span class="eyebrow">Portfolio funnel</span><h2>From demand to stayed revenue</h2></div><span class="period-pill">Illustrative monthly view</span></div><div class="funnel">${funnel.map((item, i) => `<div class="funnel-step"><div class="funnel-number">${String(i + 1).padStart(2, "0")}</div><div class="funnel-bar" style="--bar:${100 - i * 12}%"><div><span>${item[0]}</span><strong>${item[1]}</strong></div><small>${item[2]} · ${item[3]}</small></div>${i < funnel.length - 1 ? `<span class="funnel-drop">↓</span>` : ""}</div>`).join("")}</div></section><section class="split-grid conversion-lower"><article class="panel"><div class="panel-head"><div><span class="eyebrow">CRO queue</span><h2>Conversion opportunities</h2></div></div><div class="opportunity-list"><div><span class="opportunity-index">01</span><div><strong>Volga mobile booking path</strong><p>Completion fell while traffic increased. Audit speed, rate display, and room selection friction.</p></div><span class="priority high">High</span></div><div><span class="opportunity-index">02</span><div><strong>Alexander direct rate parity</strong><p>High OTA share suggests a direct-capture offer or metasearch test.</p></div><span class="priority medium">Medium</span></div><div><span class="opportunity-index">03</span><div><strong>Destination page CTR</strong><p>Three pages gained impressions but lost click-through. Refresh title and intent match.</p></div><span class="priority low">Low</span></div></div></article><article class="panel qa-card"><div class="panel-head"><div><span class="eyebrow">Tracking QA</span><h2>Trust the signal</h2></div><span class="qa-status">2 checks open</span></div><div class="qa-line"><span class="check-ring">!</span><div><strong>Revenue discrepancy</strong><p>Alexander Meta purchase revenue differs from booking engine revenue by 23%.</p></div><button class="text-button" data-ai="true">Review</button></div><div class="qa-line"><span class="check-ring good">✓</span><div><strong>GA4 booking event</strong><p>Event volume is within expected range across the portfolio.</p></div><span class="verified">Verified</span></div></article></section></div>`; }

function growthView() { return `<div class="view"><section class="hero-row compact"><div><span class="eyebrow">Growth lab</span><h1>Turn diagnosis into<br><em>controlled learning.</em></h1><p class="hero-copy">Experiments make the commercial system legible: one hypothesis, one metric, one next decision.</p></div><div class="hero-aside lab-note"><span class="eyebrow">Active learning</span><strong>3 experiments in flight</strong><span>2 need a next checkpoint this week</span><button class="primary-button" data-new-experiment="true">Create experiment <span>+</span></button></div></section><section class="panel experiment-panel"><div class="panel-head"><div><span class="eyebrow">Active experiments</span><h2>What are we testing next?</h2></div><button class="secondary-button" data-new-experiment="true">+ New experiment</button></div><div class="experiment-list">${experiments.map((e, i) => `<article class="experiment-card"><div class="experiment-index">0${i + 1}</div><div class="experiment-main"><div class="experiment-head"><div><h3>${e.name}</h3><span>${e.property}</span></div>${tag(e.status)}</div><p class="hypothesis"><span>Hypothesis</span>${e.hypothesis}</p><div class="experiment-metrics"><div><span>Metric</span><strong>${e.metric}</strong></div><div><span>Baseline</span><strong>${e.baseline}</strong></div><div><span>Target</span><strong>${e.target}</strong></div><div><span>Owner</span><strong>${e.owner}</strong></div></div></div><div class="experiment-actions"><button class="subtle-button" data-experiment-status="${i}">${e.status === "Running" ? "Mark complete" : "Mark running"} <span>${icon("arrow")}</span></button><button class="icon-button small" aria-label="More experiment options">···</button></div></article>`).join("")}</div></section><section class="architecture-strip"><div><span class="eyebrow">Operating principle</span><h2>People · Process · Technology · Data</h2><p>AI expands the amount of analysis and QA the portfolio can handle. Human judgment still owns the commercial decision.</p></div><div class="strip-flow"><span>Signal</span><i>→</i><span>Diagnosis</span><i>→</i><span>Experiment</span><i>→</i><span>Decision</span></div></section></div>`; }

function accountBrandStrategyPanel() { const p = properties.find(item => item.name === state.selected) || properties[4]; const profiles = { Volga:{promise:"Design-led Mexico City stay with a cultural point of view",audience:"Culture seeker · design traveler · high-intent city break",role:"Demand recovery",guardrail:"Do not trade distinctiveness for discount",reputation:"4.6 / 5",branded:"+18%",direct:"61%"}, "La Valise Tulum":{promise:"Barefoot luxury with scarcity, intimacy, and a sense of place",audience:"High-intent escape · wellness · design-led traveler",role:"Brand halo",guardrail:"Protect rate, scarcity, and service promise",reputation:"4.8 / 5",branded:"+24%",direct:"78%"}, "Alexander Hotel":{promise:"An urban social stay with direct, confident capture",audience:"City break · social traveler · value-aware design guest",role:"Direct recovery",guardrail:"Use value without flattening the brand",reputation:"4.5 / 5",branded:"+11%",direct:"48%"}, "NEST Baja":{promise:"Remote nature and slow travel that earns the journey",audience:"Nature seeker · long-stay · experience-led traveler",role:"Growth bet",guardrail:"Sell the destination, not only the room",reputation:"4.7 / 5",branded:"+16%",direct:"49%"}}; const profile = profiles[p.name] || {promise:`A distinctive ${p.destination} stay with a clear reason to choose direct`,audience:"Qualified destination traveler · property-fit guest",role:p.action === "Protect" ? "Margin protector" : p.action === "Direct" ? "Direct recovery" : "Portfolio account",guardrail:"Make the promise clear before scaling reach",reputation:"4.6 / 5",branded:"+12%",direct:`${p.direct}%`}; const pillarStates = [{name:"People",value:"Promise lived",tip:"Property teams and guest-facing people can deliver the experience the brand promises."},{name:"Process",value:"Handoff mapped",tip:"Brand, growth, revenue, and property teams have a clear path from insight to action."},{name:"Technology",value:p.name === "Volga" ? "Mobile QA open" : "Path monitored",tip:"Booking, feed, and measurement systems support the promise and capture demand."},{name:"Data",value:"Directional",tip:"Brand and commercial signals are connected enough to guide a test, but not yet production truth."}]; return `<section class="drawer-section account-brand-strategy"><div class="section-question"><span>Brand strategy question</span><strong>What promise should this account make—and what evidence shows it is earning preference?</strong></div><div class="account-brand-summary"><div><span>Promise</span><strong>${profile.promise}</strong></div><div><span>Audience</span><p>${profile.audience}</p></div><div><span>Portfolio role</span><b>${profile.role}</b><small>${profile.guardrail}</small></div></div><div class="account-brand-metrics"><div><span>Reputation</span><strong>${profile.reputation}</strong><small>Review health · illustrative</small></div><div><span>Branded demand</span><strong>${profile.branded}</strong><small>Search interest · illustrative</small></div><div><span>Direct preference</span><strong>${profile.direct}</strong><small>Direct mix · illustrative</small></div></div><div class="account-pillars"><span class="eyebrow">Four-pillar readiness</span>${pillarStates.map(pillar => `<div><strong>${pillar.name}</strong><span class="explainable" tabindex="0" data-tip="${pillar.tip}">${pillar.value}</span></div>`).join("")}</div><p class="brand-account-note">The account strategy is not complete until the promise, audience, experience delivery, demand signals, reputation, and direct contribution tell the same story.</p></section>`; }
function roleCharterPanel() { return `<section class="panel role-charter"><div class="panel-head"><div><span class="eyebrow">Operator remit</span><h2>In the accounts, close to the decision</h2></div><span class="period-pill">Hands-on growth owner</span></div><div class="section-question"><span>Role question</span><strong>What can I change this week across paid media, SEO, lifecycle, and the booking path?</strong></div><div class="role-charter-grid"><div><span>01 · Paid media</span><strong>Acquire the right demand</strong><p>Build, optimize, and reallocate campaigns against need dates and contribution—not traffic volume alone.</p><b>Scoreboard · acquisition cost</b></div><div><span>02 · SEO</span><strong>Earn qualified discovery</strong><p>Work directly in destination and property pages, search demand, internal links, and AEO / GEO visibility.</p><b>Scoreboard · qualified direct demand</b></div><div><span>03 · Lifecycle</span><strong>Recover and compound value</strong><p>Use abandonment, pre-arrival, post-stay, winback, and cross-property journeys to grow direct relationships.</p><b>Scoreboard · direct revenue mix</b></div><div><span>04 · Portfolio ownership</span><strong>Move fast with evidence</strong><p>Own the account view, make the call, document the rationale, and return to the result with a small team.</p><b>Cadence · weekly decisions</b></div></div><div class="role-charter-foot"><span>Remote-ready operating rule</span><strong>Workday overlap with Mexico City · asynchronous evidence · fast human approval</strong></div></section>`; }
function dashboardMapPanel() { const surfaces = [{name:"Portfolio",job:"Decide",input:"Targets · occupancy · contribution · 18 accounts",output:"Priority property + next move"},{name:"Brand & Demand",job:"Understand",input:"Promise · audience · reputation · search demand",output:"Brand guardrail + demand thesis"},{name:"Acquisition",job:"Acquire",input:"Paid media · SEO · metasearch · need dates",output:"Budget allocation + channel action"},{name:"Conversion",job:"Convert",input:"Booking path · device · funnel · QA",output:"Friction fix + direct revenue lift"},{name:"Growth Lab",job:"Execute + learn",input:"Owner · experiment · due date · outcome",output:"Decision memory + next test"}]; return `<section class="panel dashboard-map"><div class="panel-head"><div><span class="eyebrow">Information architecture</span><h2>Five surfaces, one operating loop</h2></div><span class="period-pill">How to use the OS</span></div><div class="section-question"><span>Navigation question</span><strong>Where do I go to understand the signal, make the decision, and prove the result?</strong></div><div class="dashboard-map-grid">${surfaces.map((surface,i) => `<article><span>0${i+1}</span><h3>${surface.name}</h3><b>${surface.job}</b><p><strong>Input</strong>${surface.input}</p><p><strong>Output</strong>${surface.output}</p></article>`).join("")}</div><div class="processing-loop"><span>Source data</span><i>→</i><span>QA + definitions</span><i>→</i><span>Diagnosis</span><i>→</i><span>Human decision</span><i>→</i><span>Execution</span><i>→</i><span>Measured outcome</span></div><div class="panel-footline"><span>The portfolio is the decision layer; channel tabs are workbenches; Growth Lab stores the feedback loop.</span><span class="decision-caption">One source of truth</span></div></section>`; }
function internalMachinePanel() { const cases = [{property:"Property A",signal:"92% occupied next month",problem:"Demand is already healthy.",decision:"Protect rate, direct mix, and guest quality.",action:"Do almost nothing; monitor pickup and avoid unnecessary spend."},{property:"Property B",signal:"58% occupied",problem:"Open inventory may need qualified demand.",decision:"Test whether demand can be generated profitably.",action:"Find need dates, source markets, and contribution-safe budget."},{property:"Property C",signal:"75% occupied · OTA dependent",problem:"Revenue exists, but distribution cost is high.",decision:"Shift attention to direct acquisition and parity.",action:"Improve direct benefits, SEO capture, metasearch, and lifecycle recovery."},{property:"Property D",signal:"Traffic is high · conversion is poor",problem:"The booking path is leaking value.",decision:"Fix conversion before buying more traffic.",action:"Audit mobile speed, rate display, availability, and checkout."}]; return `<section class="panel internal-machine"><div class="panel-head"><div><span class="eyebrow">Building block 3</span><h2>Understand the internal machine</h2></div><span class="period-pill">Working model · not Namron’s confirmed workflow</span></div><div class="section-question"><span>Monday morning question</span><strong>What did revenue tell me, what is the actual growth problem, and what should I change first?</strong></div><div class="machine-grid">${cases.map(item => `<article><span>${item.property}</span><strong>${item.signal}</strong><small>${item.problem}</small><p><b>Decision</b>${item.decision}</p><p><b>Hands-on move</b>${item.action}</p></article>`).join("")}</div><div class="panel-footline"><span>Same portfolio, four different interventions.</span><span class="decision-caption">Never default to “increase advertising”</span></div></section>`; }
function operatorLoopPanel() { const steps = [{number:"01",name:"Input",question:"What is happening?",detail:"Occupancy, inventory, ADR, booking pace, direct and OTA bookings, paid media, organic search, website behavior, booking engine, CRM, source markets, and budget."},{number:"02",name:"Diagnose",question:"Why is it happening?",detail:"Separate demand, traffic quality, conversion, market, offer, search visibility, booking friction, OTA dependence, tracking, and seasonality."},{number:"03",name:"Prioritize",question:"Which problem matters most?",detail:"Rank revenue opportunity, available inventory, acquisition efficiency, urgency, effort, confidence, and strategic importance."},{number:"04",name:"Execute",question:"What can I change directly?",detail:"Work inside Google Ads, Meta, SEO, landing pages, booking engine, email, CRM, tracking, creative, and budget."},{number:"05",name:"Measure",question:"Did it work?",detail:"Compare the defined baseline with the expected impact using direct revenue, cost, conversion, occupancy, and net contribution."},{number:"06",name:"Learn",question:"What happens next?",detail:"Keep, change, or stop the intervention, record the decision, and feed the actual outcome into the next review."}]; return `<section class="panel operator-loop"><div class="panel-head"><div><span class="eyebrow">Building block 4</span><h2>The operator loop</h2></div><span class="period-pill">Repeat weekly · act daily</span></div><div class="section-question"><span>Framework to memorize</span><strong>The dashboard is not the job. The job is moving from evidence to a profitable action and learning from the result.</strong></div><div class="operator-loop-grid">${steps.map(step => `<article><span>${step.number}</span><strong>${step.name}</strong><h3>${step.question}</h3><p>${step.detail}</p></article>`).join("")}</div><div class="operator-loop-footer"><span>Input → diagnose → prioritize → execute → measure → learn</span><b>That entire loop is what the Growth OS represents.</b></div></section>`; }
function accountOperatorLoopPanel() { const p = properties.find(item => item.name === state.selected) || properties[4]; const volga = p.name === "Volga"; const steps = [{name:"Input",detail:`${p.occupancy}% occupancy · ${p.direct}% direct mix · ${p.conversion}% conversion · $${p.cpb} CPB`,read:"Start with stay-date need, channel cost, owned demand, and booking quality."},{name:"Diagnose",detail:volga ? "Traffic is growing, but direct conversion is weakening." : `${p.action} is the current decision state for this account.`,read:volga ? "The likely constraint is after the click, so more reach could waste budget." : p.action === "Protect" ? "Demand is healthy; incremental spend may dilute rate or contribution." : "Confirm the constraint with source, device, availability, parity, and margin evidence."},{name:"Prioritize",detail:`Decision: ${p.action}`,read:p.action === "Grow" ? "Prioritize need dates and qualified demand before broad reach." : p.action === "Direct" ? "Prioritize owned-channel capture and distribution-cost reduction." : "Prioritize the smallest intervention that protects or improves contribution."},{name:"Execute",detail:volga ? "Mobile booking QA · parity check · abandonment recovery" : p.action === "Protect" ? "Rate protection · brand demand · guest-quality guardrails" : "Paid media · SEO capture · CRO · lifecycle recovery",read:"Queue the hands-on move with an owner, due date, baseline, and expected impact."},{name:"Measure",detail:"Direct revenue · net contribution · conversion · occupancy pace",read:"Compare against a defined baseline and stay-date window—not vanity traffic alone."},{name:"Learn",detail:"Weekly review · actual outcome · decision memory",read:"Keep, change, or stop the action, then use the result to improve the next account decision."}]; return `<section class="drawer-section account-operator-loop"><div class="section-question"><span>Account operator loop</span><strong>What do I do with this account from first signal to measured result?</strong></div><div class="account-loop-grid">${steps.map((step,i) => `<article><span>0${i + 1} · ${step.name}</span><strong>${step.detail}</strong><p>${step.read}</p></article>`).join("")}</div><div class="account-loop-footer"><span>Next proof point</span><strong>Assign an owner, set a decision date, and compare the actual result with the expected impact.</strong></div></section>`; }
function accountLogicPanel() { const p = properties.find(item => item.name === state.selected) || properties[4]; const volga = p.name === "Volga"; const rows = volga ? [{metric:"Traffic ↑ 14%",meaning:"Qualified attention is arriving, so the top-of-funnel message may be working.",diagnosis:"If booking conversion falls at the same time, the constraint is likely after the click—not reach.",focus:"Audit mobile booking speed, rate display, room selection, and message match."},{metric:"Conversion ↓ 19%",meaning:"A smaller share of booking-engine sessions becomes a confirmed reservation.",diagnosis:"The property may be paying for demand it cannot efficiently capture.",focus:"Fix the booking path before scaling paid media."},{metric:"OTA share ↑ 6%",meaning:"More bookings are being captured through a higher-cost distribution channel.",diagnosis:"Direct preference or parity may be leaking at the point of choice.",focus:"Check direct versus OTA rates, benefits, and mobile friction."}] : [{metric:`${p.occupancy}% occupancy`,meaning:"The share of available rooms expected to be occupied in the selected stay-date window.",diagnosis:p.action === "Protect" ? "Demand is healthy enough that incremental spend may dilute rate or margin." : "Open inventory may justify targeted demand, but only on the dates that need it.",focus:p.action === "Protect" ? "Protect rate, direct mix, and guest quality." : "Prioritize need dates, qualified source markets, and contribution."},{metric:`${p.direct}% direct mix`,meaning:"The share of bookings attributed to Namron-owned channels under the chosen production definition.",diagnosis:p.direct < 65 ? "The property may be relying too heavily on OTA distribution or losing direct intent during the booking path." : "Owned demand is relatively strong; protect the promise and reduce unnecessary acquisition cost.",focus:p.direct < 65 ? "Review parity, direct benefits, SEO capture, and lifecycle recovery." : "Use direct economics to protect rate and avoid buying demand already present."},{metric:`${p.conversion}% conversion`,meaning:"The percentage of qualified booking-engine sessions that become confirmed reservations.",diagnosis:p.conversion < 3 ? "Demand quality, page promise, device experience, or availability may be constraining revenue." : "The booking path is a relative strength; investigate whether more qualified demand can be captured.",focus:p.conversion < 3 ? "Diagnose device, room selection, rate, and checkout friction." : "Scale carefully while monitoring cancellation and contribution quality."}]; return `<section class="drawer-section account-logic"><div class="section-question"><span>Account logic</span><strong>What might be happening, what does the metric mean, and what should we focus on next?</strong></div><div class="logic-grid">${rows.map(row => `<article><span class="logic-metric">${row.metric}</span><strong>What it means</strong><p>${row.meaning}</p><strong>Possible read</strong><p>${row.diagnosis}</p><strong>Focus now</strong><p class="logic-focus">${row.focus}</p></article>`).join("")}</div><div class="logic-goal"><span>Goal connection</span><strong>${volga ? "Recover profitable direct demand without increasing spend until the booking path can convert it." : `Pursue ${p.action.toLowerCase()} for ${p.name} by connecting stay-date need, direct economics, brand promise, and guest quality.`}</strong></div></section>`; }
function accountOperatorLensPanel() { const p = properties.find(item => item.name === state.selected) || properties[4]; const lifecycle = p.action === "Protect" ? "Mature" : p.action === "Investigate" ? "Repositioning" : p.demand === "Soft" ? "Ramp-up" : "Mature / optimize"; const lifecycleTip = {Mature:"Protect contribution, rate, reputation, and direct preference.","Repositioning":"Prove the new demand thesis before scaling investment.","Ramp-up":"Build qualified demand, pickup pace, and direct capture.","Mature / optimize":"Improve efficiency and conversion before adding spend."}[lifecycle]; const lenses = [{name:"Lifecycle",value:lifecycle,question:"What does this property need at this stage?",read:lifecycleTip},{name:"Unit economics",value:`$${p.cpb} CPB · ${p.roas}x ROAS`,question:"Can the next dollar create profitable demand?",read:"Read acquisition cost with ADR, cancellation, OTA commission, and net contribution—not ROAS alone."},{name:"Direct value",value:`${p.direct}% direct mix`,question:"Where is owned-channel value leaking?",read:p.direct < 65 ? "Prioritize parity, direct benefits, SEO capture, and lifecycle recovery." : "Protect direct preference and avoid buying demand already present."},{name:"Need date",value:`${p.occupancy}% occupancy`,question:"Does this property need more demand now?",read:p.occupancy < 65 ? "Find the exact stay dates, source markets, and room types that need support." : "Avoid indiscriminate reach; protect rate and fill only the marginal gap."},{name:"Guest quality",value:`${p.conversion}% conversion`,question:"Is the demand qualified and can the path convert it?",read:p.conversion < 3 ? "Investigate promise, device, availability, rate display, and checkout friction." : "Scale carefully while checking cancellations, length of stay, and contribution."},{name:"Control surface",value:p.action,question:"What can I change directly this week?",read:p.action === "Grow" ? "Paid media, SEO landing pages, CRO, and lifecycle recovery are the immediate levers." : p.action === "Protect" ? "Rate protection, brand search, direct benefits, and guest-quality guardrails." : "Start with diagnosis and one controlled intervention before reallocating budget."}]; return `<section class="drawer-section account-operator-lens"><div class="section-question"><span>Operator lens</span><strong>How should I assess this account before I touch the budget, channel, or booking path?</strong></div><div class="operator-lens-grid">${lenses.map(lens => `<article><span>${lens.name}</span><strong>${lens.value}</strong><small>${lens.question}</small><p>${lens.read}</p></article>`).join("")}</div><div class="operator-rule"><span>Decision rule</span><strong>Match the intervention to lifecycle stage, need date, direct value, guest quality, and the lever you can control.</strong></div></section>`; }
function accountTabPanel() { const p = properties.find(item => item.name === state.selected) || properties[4]; const panels = { Overview:{label:"Account overview",title:"What deserves attention before I change anything?",body:`${p.name} is currently a ${p.action.toLowerCase()} account: connect stay-date need, conversion quality, direct value, and net contribution before scaling a tactic.`,next:"Use the operator lens and account logic below to defend the first decision."}, Acquisition:{label:"Acquisition workbench",title:"Can I create or capture profitable demand?",body:`Read ${p.roas}x ROAS and $${p.cpb} CPB alongside ${p.occupancy}% occupancy, ADR, OTA commission, and need dates.`,next:"Work in Google, Meta, metasearch, SEO, and lifecycle only where the account has a measurable demand gap."}, Conversion:{label:"Conversion workbench",title:"Is the account losing value after the click?",body:`Booking conversion is ${p.conversion}%. Compare mobile and desktop booking-engine sessions, room selection, rate display, availability, checkout, and confirmation events.`,next:"Fix the highest-confidence friction before buying more traffic."}, Experiments:{label:"Experiment workbench",title:"What is the smallest test that can change the decision?",body:`Design one hypothesis for ${p.name} with a baseline, target, owner, due date, expected impact, and stop rule.`,next:"Record the outcome so this account becomes learning data—not just a recurring report."} }; const panel = panels[state.accountTab] || panels.Overview; return `<section class="account-tab-panel"><span class="eyebrow">${panel.label}</span><strong>${panel.title}</strong><p>${panel.body}</p><small>${panel.next}</small></section>`; }
function accountControlRoomPanel() { const p = properties.find(item => item.name === state.selected) || properties[4]; const rooms = {Volga:23,"La Valise Tulum":11,"Alexander Hotel":63,"NEST Baja":12}[p.name] || 18; const repeat = p.action === "Protect" ? "24%" : p.action === "Direct" ? "17%" : "11%"; const season = p.destination === "Tulum" ? "Peak: Nov–Apr · shoulder: May–Jun" : p.destination === "Mexico City" ? "Peak: Oct–Mar · event-led spikes" : "Peak and shoulder need validation"; const tiles = [{name:"Inventory",value:`${rooms} rooms · ${p.occupancy}% occ.`,question:"Where is sellable inventory open?",read:"Read rooms, room type, restrictions, stay dates, pickup pace, and 90-day occupancy before adding reach."},{name:"Customers",value:`${repeat} repeat direct`,question:"Who is most valuable to this account?",read:"Separate new, repeat, domestic, international, high-LTV, cancellation-prone, and lifecycle-ready guests."},{name:"Seasonality",value:season,question:"When should I spend or protect rate?",read:"Map need dates, booking window, source markets, events, weather, and destination patterns—not monthly averages alone."},{name:"Demand",value:`${p.demand} · ${p.direct}% direct`,question:"Is demand healthy and where is it coming from?",read:"Connect forward pace, branded and nonbrand search, source markets, direct preference, and OTA share."},{name:"Conversion",value:`${p.conversion}% booking conv.`,question:"Can qualified intent become a booking?",read:"Segment the funnel by device, landing page, room type, rate, availability, checkout, and confirmation event."},{name:"OTA dependency",value:`${100 - p.direct}% non-direct`,question:"What distribution cost are we carrying?",read:"Compare OTA share, commission, parity, visibility, cancellations, and direct benefits before shifting demand."},{name:"Economics",value:`$${p.cpb} CPB · ${p.roas}x ROAS`,question:"Does the next dollar create net value?",read:"Defend contribution after media, OTA commission, payment fees, discounts, cancellations, and stay quality."},{name:"Paid media",value:`$${p.cpb} CPB`,question:"Which campaign or audience deserves budget?",read:"Work at property × campaign × stay-date grain with search intent, creative, marginal ROAS, and incrementality."},{name:"SEO / AEO / GEO",value:"Visibility · intent · answerability",question:"Can the right guest discover and understand this property?",read:"Audit technical health, destination intent, structured facts, internal links, reviews, and AI-readable property evidence."},{name:"Lifecycle",value:`${repeat} repeat direct`,question:"How do we recover and compound demand?",read:"Use abandonment, pre-arrival, post-stay, winback, cross-property, and high-value guest journeys."}]; return `<section class="drawer-section account-control-room"><div class="section-question"><span>Account control room</span><strong>What do I need to know and operate directly for ${p.name}?</strong></div><div class="control-room-grid">${tiles.map(tile => `<article><span>${tile.name}</span><strong>${tile.value}</strong><small>${tile.question}</small><p>${tile.read}</p></article>`).join("")}</div><div class="control-room-note"><span>Production rule</span><strong>Every tile should eventually reconcile to a source, freshness timestamp, definition, confidence level, and accountable next action.</strong></div></section>`; }
function app() { return `<div class="app-shell">${header()}<main>${demoBanner()}<div class="workspace">${state.tab === "Portfolio" ? portfolioView() : state.tab === "Acquisition" ? acquisitionView() : state.tab === "Conversion" ? conversionView() : state.tab === "Brand & Demand" ? brandView() : growthView()}${storyMode()}</div></main>${state.selected ? detailDrawer() : ""}${aiDrawer()}${state.modal ? architectureModal() : ""}<div class="toast ${state.toast ? "show" : ""}">${state.toast}</div></div>`; }

function organizeInformationArchitecture() {
  const view = document.querySelector(".view");
  if (!view) return;
  const active = state.tab === "Portfolio" ? "Decision" : state.tab === "Acquisition" || state.tab === "Brand & Demand" ? "Evidence" : state.tab === "Conversion" ? "Diagnosis" : "Action";
  const hero = view.querySelector(".hero-row");
  if (hero && !view.querySelector(".workflow-rail")) hero.insertAdjacentHTML("afterend", workflowRail(active));
  if (state.tab === "Portfolio") {
    view.querySelector(".pillar-panel")?.remove();
    view.querySelector(".surface-panel")?.remove();
    const metrics = view.querySelector(".metrics-grid");
    if (metrics) {
      metrics.insertAdjacentHTML("beforebegin", '<div class="section-marker"><span class="eyebrow">Decision layer</span><span>Portfolio pulse · the six numbers to act on first</span></div>');
      metrics.querySelectorAll(".metric:nth-child(n+7)").forEach(metric => metric.classList.add("supporting-metric"));
      view.querySelector(".measurement-note")?.insertAdjacentHTML("beforebegin", '<div class="secondary-metrics-note"><span>Supporting economics</span><strong>LTV · CPV · ADR · OTA commission</strong><small>Use these to defend quality and distribution cost after the core decision.</small></div>');
    }
    view.querySelector(".portfolio-panel")?.insertAdjacentHTML("afterend", portfolioContextPanel());
    view.querySelector(".workflow-rail")?.insertAdjacentHTML("afterend", portfolioPlanPanel());
  }
  if (state.tab === "Acquisition") view.insertAdjacentHTML("beforeend", distributionHealthPanel() + commercialEconomicsPanel());
  if (state.tab === "Acquisition") {
    const rail = view.querySelector(".workflow-rail");
    const channelPanel = view.querySelector(".view > .panel");
    const split = view.querySelector(".split-grid");
    const demand = view.querySelector(".demand-panel");
    const direct = view.querySelector(".direct-ota");
    if (split && demand && direct) split.insertBefore(demand, direct);
    if (rail && channelPanel && split) { rail.after(split); split.after(channelPanel); }
  }
  if (state.tab === "Brand & Demand") {
    const scorecard = view.querySelector(".brand-scorecard");
    if (scorecard && !view.querySelector(".pillar-measurement")) scorecard.insertAdjacentHTML("beforebegin", pillarMeasurementPanel());
  }
  if (state.tab === "Conversion") view.insertAdjacentHTML("beforeend", dataTrustPanel());
  if (state.tab === "Growth Lab") {
    view.querySelector(".workflow-rail")?.insertAdjacentHTML("afterend", roleCharterPanel() + internalMachinePanel() + operatorLoopPanel() + dashboardMapPanel());
    view.insertAdjacentHTML("beforeend", operatingPillars() + revenueSurfaces() + humanLoopPanel() + decisionLogPanel() + tacticsQueuePanel() + dataAccessPanel() + sourceDeskPanel());
  }
  if (state.selected) { document.querySelector(".drawer-tabs")?.querySelectorAll("button").forEach((button, i) => button.classList.toggle("active", ["Overview", "Acquisition", "Conversion", "Experiments"][i] === state.accountTab)); document.querySelector(".drawer-tabs")?.insertAdjacentHTML("afterend", accountTabPanel()); document.querySelector(".account-stat-strip")?.insertAdjacentHTML("afterend", detailTargetPanel() + detailClarityPanel() + accountBrandStrategyPanel() + accountControlRoomPanel() + accountOperatorLensPanel() + accountOperatorLoopPanel() + accountLogicPanel() + accountJourneyPanel() + implementationPlaybook()); }
}

function enhanceExplanations() {
  const definitions = { "Account": "The individual hotel or commercial account being managed.", "Demand": "Forward demand strength based on stay-date pace, availability, and current need.", "Direct mix": "The share of bookings, room nights, or revenue attributed to Namron-owned channels. The production definition must be chosen explicitly.", "Occ.": "Stay-date occupancy: occupied rooms divided by available rooms for the selected period.", "ROAS": "Attributed booking revenue divided by media spend. It does not automatically equal profit.", "CPB": "Cost per confirmed booking: acquisition spend divided by confirmed bookings.", "Conv.": "Booking-engine sessions that become confirmed reservations.", "Decision": "The recommended portfolio action based on demand, economics, conversion, and confidence.", "RevPAR": "Revenue per available room: room revenue divided by available room nights.", "Pickup pace": "New bookings added for future stay dates compared with a prior snapshot.", "Booking window": "Average number of days between booking and arrival.", "Length of stay": "Average number of nights per stayed booking.", "QA": "Data-quality checks that must pass before a number should drive a decision.", "Source state": "Whether the number is connected, estimated, modeled, or illustrative.", "Last 30 days": "The comparison window used for the current illustrative view.", "Illustrative portfolio view": "A demo calculation showing the intended operating model, not internal Namron performance.", "Confidence · directional": "A directional confidence label; production confidence must come from completeness, reconciliation, and attribution checks." };
  document.querySelectorAll("th, .period-pill, .status-chip, .qa-status, .qa-good, .decision-status, .lifecycle-list strong, .health-check-grid em").forEach(element => { const key = element.textContent.trim(); const definition = definitions[key]; if (definition) { element.classList.add("explainable"); element.setAttribute("tabindex", "0"); element.dataset.tip = definition; } });
  const extraDefinitions = { "Direct net revenue": "Revenue retained after payment fees and discounts, before acquisition cost.", "OTA distribution cost": "Commission and channel fees paid to acquire or fulfill OTA bookings.", "Contribution margin": "Net revenue remaining after distribution, acquisition, payment, discount, and cancellation costs.", "Direct value advantage": "Estimated retained value from a direct booking compared with an equivalent OTA booking.", "Source coverage": "The share of required source systems currently mapped and available to the metric layer.", "Freshness": "Time since the latest source data was successfully loaded.", "Attribution": "The rule used to assign a booking or revenue event to a channel.", "Exceptions": "Data-quality or reconciliation issues that could change a decision.", "AEO": "Answer Engine Optimization: making property facts easy for AI assistants to retrieve and explain.", "SEO": "Search Engine Optimization: earning qualified organic visibility and clicks.", "GEO": "Generative Experience Optimization: improving representation in AI-generated travel answers.", "Direct revenue target": "The approved revenue outcome the portfolio or property is expected to achieve in the selected planning period.", "Current run-rate": "The annualized or periodized revenue implied by current performance if the existing pace continues. It is a forecast, not booked revenue.", "Target direct mix": "The desired share of bookings, room nights, or revenue coming through owned direct channels.", "Plan variance": "The difference between the current forecast or run-rate and the approved target. Positive is only good if margin and guest quality are protected.", "Portfolio goal": "The commercial outcome the team is trying to achieve, agreed with revenue and leadership.", "Forecast at current pace": "A projection based on current performance, seasonality assumptions, and available evidence.", "Positive pace · protect margin": "The plan appears ahead, so the next decision may be protecting rate and contribution rather than buying more demand.", "90-day occ. target": "The intended stay-date occupancy level over the next 90 days for this property.", "Direct mix target": "The intended direct contribution for this property after considering demand, rate, channel cost, and lifecycle stage.", "Decision lens": "The action category used to prioritize this property relative to its current commercial need." };
  document.querySelectorAll(".context-stats span, .trust-grid span, .economics-grid span, .search-code, .plan-grid span, .plan-grid strong, .plan-grid small, .goal-grid span, .goal-grid strong, .goal-grid small, .goal-status").forEach(element => { const definition = extraDefinitions[element.textContent.trim()]; if (definition) { element.classList.add("explainable"); element.setAttribute("tabindex", "0"); element.dataset.tip = definition; } });
  document.querySelectorAll(".tag, .demand").forEach(element => { const value = element.textContent.trim(); const definitionsByValue = { Protect: "Protect rate and direct mix when forward occupancy and demand are already strong.", Grow: "Create incremental demand when inventory needs support and economics can tolerate investment.", Optimize: "Improve efficiency or conversion before adding meaningful budget.", Direct: "Reduce OTA dependence by improving owned-channel capture and parity.", Investigate: "Pause scaling until a data, demand, or distribution issue is understood.", Strong: "Forward demand is healthy relative to available inventory.", Medium: "Demand is adequate but needs monitoring or selective intervention.", Soft: "Open inventory or weak pace creates a potential demand need." }; if (definitionsByValue[value]) { element.classList.add("explainable"); element.setAttribute("tabindex", "0"); element.dataset.tip = definitionsByValue[value]; } });
  const detailDefinitions = { "Rooms": "The number of sellable rooms or keys in this property. It provides the denominator for occupancy and RevPAR.", "ADR": "Average Daily Rate: average room revenue per occupied room night. Read it with occupancy and cancellation rate, not in isolation.", "90 day occ.": "Expected stay-date occupancy over the next 90 days. It helps determine whether the property needs demand, rate protection, or conversion work.", "Signals": "The observed changes that triggered the account diagnosis. Signals are evidence, not yet a recommendation.", "Diagnosis": "The interpretation of the signals: what is likely happening, what is uncertain, and which constraint should be addressed first.", "Recommended actions": "The smallest set of actions designed to test or resolve the diagnosis. Each action should have an owner, due date, and expected impact.", "Acquisition": "How the property is creating and capturing demand across paid, organic, metasearch, and lifecycle channels.", "Conversion": "Where demand becomes booking intent and confirmed reservations, including device and booking-engine friction.", "Experiments": "Controlled tests with a hypothesis, primary metric, baseline, target, owner, and decision date.", "Account": "The individual hotel or commercial account being managed.", "Current": "The observed value in the selected illustrative window.", "Target": "The intended value for the selected planning window. It should come from revenue and property priorities, not an arbitrary benchmark." };
  document.querySelectorAll(".detail-drawer .account-stat-strip span, .detail-drawer .drawer-section > .eyebrow, .detail-drawer .drawer-tabs button, .detail-drawer .account-switcher > span").forEach(element => { const definition = detailDefinitions[element.textContent.trim()]; if (definition) { element.classList.add("explainable"); element.setAttribute("tabindex", "0"); element.dataset.tip = definition; } });
}

function addSectionQuestions() {
  const questions = { "Are we on pace for the revenue we want?": "How are we doing against the portfolio revenue target, and what gap needs attention?", "Which properties need attention?": "Which property needs attention, and what decision should we make?", "Need dates before more spend": "Where is inventory open, and is paid demand the right lever?", "Measure the stage, not just the score": "What is this property trying to achieve at its current lifecycle stage?", "What the acquisition machine is producing": "Which channels are creating qualified demand at an acceptable cost?", "Direct vs OTA": "Where can direct mix improve contribution after distribution costs?", "Forward demand": "Which stay dates need demand, rate protection, or no intervention?", "Can the portfolio actually sell?": "Are the feeds, rates, inventory, and booking path healthy enough to convert demand?", "Optimize contribution, not just ROAS": "Which channel creates the most profitable incremental contribution?", "From demand to stayed revenue": "Where are guests dropping before they become stayed revenue?", "Conversion opportunities": "What is the next conversion action worth testing?", "Trust the signal": "Can we trust the number before we act on it?", "Separate signal from certainty": "What do we know, how fresh is it, and what remains uncertain?", "What are we testing next?": "Which hypothesis should the team learn from next?", "Four pillars behind the growth system": "What operating capability must support growth across the portfolio?", "Every revenue surface should have a growth loop": "Where else can Namron create value beyond the room?", "Insight becomes value when someone owns the next move": "Who owns the next decision, and how will we learn from the outcome?", "Recommendations with a memory": "Which recommendations were accepted, rejected, or still waiting for a decision?", "What needs to be connected": "Which source systems are required before this becomes a production operating system?", "From signal to decision": "How does a source signal become a human decision and measurable execution?", "Is brand demand becoming commercial demand?": "Are we building preference, not just buying traffic?", "Brand strategy creates resonance; the four pillars make it repeatable": "How does a distinctive idea become a measurable, repeatable commercial system?", "Every property has a role and a promise": "What promise and audience should guide this property’s growth decisions?", "Does the promise survive the click?": "Does the creative attract the right guest and preserve the property’s distinctiveness?", "What are guests actually remembering?": "Which experience themes are strengthening or weakening future demand?", "Growth recommendations must protect the soul of the property": "Can this action improve contribution without damaging brand equity or guest trust?" };
  document.querySelectorAll(".panel, .pillar-panel, .surface-panel, .architecture-strip").forEach(section => { if (section.querySelector(".section-question")) return; const heading = section.querySelector("h2"); const question = heading && questions[heading.textContent.trim()]; if (!question) return; const head = section.querySelector(".panel-head") || heading.parentElement; head.insertAdjacentHTML("afterend", `<div class="section-question"><span>Growth question</span><strong>${question}</strong></div>`); });
}

function addOfficialPropertyLink() { const links = { "La Valise Tulum": "https://www.lavalisetulum.com/", "XELA Tulum": "https://www.xelatulum.com/", "Maison Felix Miami": "https://www.maisonfelix.miami/", "La Valise Mexico City": "https://www.lavalisecdmx.com/", "Volga": "https://hotelvolga.mx/", "La Valise Los Cabos": "https://www.lavaliseloscabos.com/", "The William New York": "https://www.thewilliamnyc.com/", "La Valise San Miguel": "https://www.lavalisesma.com/", "La Valise Mazunte": "https://www.lavalisemazunte.com/", "Alexander Hotel": "https://alexanderhotel.mx/", "El Cortés": "https://elcortes.mx/", "NEST Baja": "https://www.nestbaja.com/", "Encantada": "https://www.encantada.com/", "Bespoke": "https://thebespoke.com/", "Radhoo": "https://www.theradhootulum.com/", "NEST Tulum": "https://www.nesttulum.com/", "MUSA": "https://www.stayatmusa.mx/", "NEST Los Cabos": "https://www.nestloscabos.com/" }; const drawer = document.querySelector(".detail-drawer"); const title = drawer?.querySelector(".drawer-head h2"); if (!drawer || !title || !links[title.textContent.trim()] || drawer.querySelector(".official-property-link")) return; title.insertAdjacentHTML("afterend", `<a class="official-property-link" href="${links[title.textContent.trim()]}" target="_blank" rel="noreferrer">Open official property site ↗</a>`); }

function render() { document.querySelector("#app").innerHTML = app(); bind(); organizeInformationArchitecture(); enhanceExplanations(); addSectionQuestions(); addOfficialPropertyLink(); }

function toast(message) { state.toast = message; render(); setTimeout(() => { state.toast = ""; render(); }, 2600); }

function bind() {
  document.querySelectorAll("[data-tab]").forEach(button => button.addEventListener("click", () => { state.tab = button.dataset.tab; render(); }));
  document.querySelectorAll("[data-filter]").forEach(select => select.addEventListener("change", () => { state[select.dataset.filter] = select.value; render(); }));
  document.querySelectorAll("[data-property]").forEach(element => element.addEventListener("click", () => { state.selected = element.dataset.property; state.tab = "Portfolio"; render(); }));
  document.querySelectorAll(".property-row").forEach(element => { element.setAttribute("tabindex", "0"); element.setAttribute("role", "button"); element.setAttribute("aria-label", `Open ${element.dataset.property} account detail`); element.addEventListener("keydown", event => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); state.selected = element.dataset.property; state.tab = "Portfolio"; render(); } }); });
  document.querySelectorAll("[data-drawer-close]").forEach(element => element.addEventListener("click", () => { state.selected = null; render(); }));
  document.onkeydown = event => { if (event.key !== "Escape") return; if (state.modal) state.modal = false; else if (state.aiOpen) state.aiOpen = false; else if (state.selected) state.selected = null; else if (state.storyOpen) state.storyOpen = false; render(); };
  document.querySelectorAll(".drawer-tabs button").forEach((button, i) => button.addEventListener("click", () => { state.accountTab = ["Overview", "Acquisition", "Conversion", "Experiments"][i]; render(); }));
  document.querySelectorAll("[data-ai='true']").forEach(element => element.addEventListener("click", () => { state.aiOpen = true; render(); }));
  document.querySelectorAll("[data-ai-close]").forEach(element => element.addEventListener("click", () => { state.aiOpen = false; render(); }));
  document.querySelectorAll("[data-story-next]").forEach(element => element.addEventListener("click", () => { if (state.storyStep < 2) state.storyStep += 1; else { state.selected = "Volga"; state.tab = "Portfolio"; } render(); }));
  document.querySelectorAll("[data-story-close]").forEach(element => element.addEventListener("click", () => { state.storyOpen = false; render(); }));
  document.querySelectorAll("[data-story-open]").forEach(element => element.addEventListener("click", () => { state.storyOpen = true; render(); }));
  document.querySelectorAll("[data-architecture]").forEach(element => element.addEventListener("click", () => { state.modal = true; render(); }));
  document.querySelectorAll("[data-modal-close]").forEach(element => element.addEventListener("click", (event) => { if (event.target === element || element.dataset.modalClose !== undefined) { state.modal = false; render(); } }));
  document.querySelectorAll("[data-insight]").forEach(element => element.addEventListener("click", () => { const insight = insights[Number(element.dataset.insight)]; if (insight.target === "Volga") { state.aiOpen = false; state.selected = "Volga"; state.tab = "Portfolio"; render(); } else { state.aiOpen = false; state.tab = insight.target; toast(`${insight.action} queued for the ${insight.target} view.`); } }));
  document.querySelectorAll("[data-add-review]").forEach(element => element.addEventListener("click", () => toast(`${element.dataset.addReview} added to the weekly commercial review.`)));
  document.querySelectorAll("[data-account-next]").forEach(element => element.addEventListener("click", () => { const current = properties.findIndex(item => item.name === state.selected); state.selected = properties[(current + 1) % properties.length].name; render(); }));
  document.querySelectorAll("[data-ai-action]").forEach(element => element.addEventListener("click", () => toast(`${element.dataset.aiAction} queued for the connected portfolio workflow.`)));
  document.querySelectorAll("[data-reset]").forEach(element => element.addEventListener("click", () => { state.destination = "All destinations"; state.action = "All actions"; state.demand = "All demand"; render(); }));
  document.querySelectorAll("[data-new-experiment]").forEach(element => element.addEventListener("click", () => { if (!state.experimentAdded) { experiments.push({ name: "New portfolio test", property: "Choose account", hypothesis: "A controlled intervention should improve a defined commercial outcome.", metric: "Direct contribution", baseline: "Set baseline", target: "Set target", status: "Planning", owner: "Growth" }); state.experimentAdded = true; } toast("New experiment added to the illustrative Growth Lab."); }));
  document.querySelectorAll("[data-experiment-status]").forEach(element => element.addEventListener("click", () => { const experiment = experiments[Number(element.dataset.experimentStatus)]; if (experiment) experiment.status = experiment.status === "Running" ? "Complete" : experiment.status === "Planning" ? "Running" : "Planning"; render(); toast(`${experiment?.name || "Experiment"} status updated.`); }));
  document.querySelectorAll(".experiment-actions .icon-button").forEach((element, i) => element.addEventListener("click", () => toast(`Experiment ${i + 1} options queued for review.`)));
  document.querySelectorAll("[data-decision]").forEach(element => element.addEventListener("click", () => { const [id, status] = element.dataset.decision.split(":"); state.decisionStatus[id] = status; state.tab = "Growth Lab"; render(); toast(`${status} decision recorded in the illustrative ledger.`); }));
  document.querySelectorAll("[data-tactic]").forEach(element => element.addEventListener("click", () => toast(`${element.dataset.tactic} tactic added to the implementation queue.`)));
}

render();
